equipmentUniques={["Ab Aeterno, Grand Cuisses"]={["base"]="Grand Cuisses",["en"]="Ab Aeterno",["flavour"]={["en"]={"His enemy was for endurance forged. His own waned."},["zh"]={"他的敌人精于鏖战，而他心勉力衰。"}},["zh"]="无始之时"},["Adonia's Ego, Siphoning Wand"]={["base"]="Siphoning Wand",["en"]="Adonia's Ego",["flavour"]={["en"]={"Adonia rose with eyes afire, emanating a ghastly aura, and","broke off a carving from the wall of the Throne Room.","\"You think me powerless without my wand? Insult me again!\""},["zh"]={"阿多尼娅腾空，双眼燃着火焰，身周弥漫可怖气息；","她自王座厅的墙上折下一块雕刻。","“你以为没了魔杖我便无能？你真口出狂言！”"}},["zh"]="阿多尼娅的自我"},["Aerisvane's Wings, Burnished Gauntlets"]={["base"]="Burnished Gauntlets",["en"]="Aerisvane's Wings",["flavour"]={["en"]={"The strongest souls are forged through struggle and defeat."},["zh"]={"苦难与挫折的锤炼，造就了最坚强的灵魂。"}},["zh"]="艾瑞斯维恩之翼"},["Against the Darkness, Time-Lost Diamond"]={["base"]="Time-Lost Diamond",["effectBlocks"]={{["lines"]={"Notable Passive Skills in Radius also grant Allocated Small Passive Skills in Radius grant nothing"},["order"]={},["zh"]="范围内的核心天赋同时提供\n范围内已配置的小型天赋不提供任何加成"}},["en"]="Against the Darkness",["flavour"]={["en"]={"After the fires, in the depths of the Winter of the World, all life in the Vastiri banded together. Whether serpent, hyena, human, or golem, hated enemies clasped hand to claw, built refuge, and fought side by side against the Abyssals. Thus, the Third Pact was born."},["zh"]={"烈焰熄灭，世界之冬降临，瓦斯提里的众生依偎在一起。毒蛇，土狼，人类和傀儡，彼此憎恨的敌人携手并肩。它们兴建了避难所，共同对抗深渊的力量。第三盟约由此诞生了。"}},["zh"]="抗衡黑暗"},["Alkem Eira, Blazon Crest Shield"]={["base"]="Blazon Crest Shield",["en"]="Alkem Eira",["flavour"]={["en"]={"May your resolve never waver."},["zh"]={"愿你的决心永不动摇。"}},["zh"]="神谕"},["Alpha's Howl, Armoured Cap"]={["base"]="Armoured Cap",["en"]="Alpha's Howl",["flavour"]={["en"]={"Nature respects the strong","And paints the snow red","With the blood of the weak"},["zh"]={"自然滋养着强悍的灵魂，","雪地染上鲜红的血痕——","那是孱弱者的牺牲。"}},["zh"]="极地之眼"},["Amor Mandragora, Changeling Talisman"]={["base"]="Changeling Talisman",["en"]="Amor Mandragora",["flavour"]={["en"]={"A sensitive few among the first settlers of Ezomyr","followed the wisps by canoe. On a misty forested","island, Cirel of Tarth stood waiting to greet them."},["zh"]={"艾兹麦首批拓荒者中，几位心有所感之人","循微光乘舟而去。在雾霭笼罩的林中岛上，","塔斯的布莉姬正静候他们的到来。"}},["zh"]="爱神曼陀罗"},["Andvarius, Gold Ring"]={["base"]="Gold Ring",["en"]="Andvarius",["flavour"]={["en"]={"Danger is the price of wealth."},["zh"]={"不入险处，焉得巨富?"}},["zh"]="贪欲之记"},["Apep's Supremacy, Voodoo Focus"]={["base"]="Voodoo Focus",["en"]="Apep's Supremacy",["flavour"]={["en"]={"Give him your body, and your burdens will follow."},["zh"]={"向他献出你的躯体，你的负担也会随之而去。"}},["zh"]="艾普的霸权"},["Apron of Emiran, Hermit Garb"]={["base"]="Hermit Garb",["en"]="Apron of Emiran",["flavour"]={["en"]={"\"Prepare the rack, boy. And be careful with those hooks!\"","- the Master Torturer's last words"},["zh"]={"“搭好架子，小子。当心铁钩！”","——拷问大师的遗言"}},["zh"]="艾米兰的兜裙"},["Arakaali's Gift, Antidote Charm"]={["base"]="Antidote Charm",["effectBlocks"]={{["lines"]={"Immune to Poison"},["order"]={},["zh"]="免疫中毒"}},["en"]="Arakaali's Gift",["flavour"]={["en"]={"Devotees of the Goddess of Lust","needed never fear her sting."},["zh"]={"放荡女神的信徒永远无需害怕她的毒刺。"}},["zh"]="阿拉卡力的礼物"},["Arvil's Wheel, Hardwood Targe"]={["base"]="Hardwood Targe",["en"]="Arvil's Wheel",["flavour"]={["en"]={"The unending carnage of war","mercilessly grinds away","at body and mind."},["zh"]={"漫漫无期的鏖战","无情地磨碎了","肉体与心灵。"}},["zh"]="阿维尔之轮"},["Ashrend, Pathfinder Coat"]={["base"]="Pathfinder Coat",["en"]="Ashrend",["flavour"]={["en"]={"The blasted oak stands forever."},["zh"]={"橡树虽已枯萎，依旧永世屹立。"}},["zh"]="拂烬"},["Asphyxia's Wrath, Broadhead Quiver"]={["base"]="Broadhead Quiver",["en"]="Asphyxia's Wrath",["flavour"]={["en"]={"Mist of breath","Icing to lips and throat","As the warm ones choke and fall","Upon the frozen wasteland."},["zh"]={"如斯雾气，化为冰霜刺进口鼻","那是冻原旅人窒息倒地前","最后一次的呼吸。"}},["zh"]="冰灵之吼"},["Assailum, Closed Helm"]={["base"]="Closed Helm",["en"]="Assailum",["flavour"]={["en"]={"A moment of calm before the battle can end the war."},["zh"]={"从容一击，息鼓偃旗。"}},["zh"]="千里狙敌"},["Astramentis, Stellar Amulet"]={["base"]="Stellar Amulet",["en"]="Astramentis",["flavour"]={["en"]={"Mindless rage will shake the world,","Cunning lies will bend it.","Reckless haste will break the world,","And into darkness send it."},["zh"]={"盲目的愤怒引起纷争，","狡诈的谎言让战火停歇；","无知的莽撞造成仇恨，","而无尽黑暗将吞噬一切。"}},["zh"]="均衡之符"},["Atsak's Sight, Veiled Mask"]={["base"]="Veiled Mask",["en"]="Atsak's Sight",["flavour"]={["en"]={"Remaining unseen, the Dishonoured Assassin struck","only in the depths of the harshest sandstorms."},["zh"]={"无荣的刺客掩盖了行踪，","只待最猛烈沙暴才出手。"}},["zh"]="阿萨克的凝视"},["Atziri's Acuity, Moulded Mitts"]={["base"]="Moulded Mitts",["en"]="Atziri's Acuity",["flavour"]={["en"]={"\"The heart is the herald.","It will tell me when it is best to strike.\"","- Atziri, Queen of the Vaal"},["zh"]={"“心脏是最佳传令官，","让我知道何时该出击迎战。”","- 瓦尔女王阿兹里"}},["zh"]="阿兹里的捷思"},["Atziri's Contempt, Pronged Spear"]={["base"]="Pronged Spear",["en"]="Atziri's Contempt",["flavour"]={["en"]={"\"My people? I'm not doing this for them.","They belong to me. They want this for me.","Their sacrifice is a gift they give out of love","and adoration... I deserve it. I am their Queen.\""},["zh"]={"“我的人民？我这么做可不是为了他们。","他们本就属于我，是他们甘愿为我付出。","他们的牺牲是出于爱与崇敬的献礼……","我配得上这一切。因为我是他们的女王。”"}},["zh"]="阿兹里的蔑视"},["Atziri's Disdain, Gold Circlet"]={["base"]="Gold Circlet",["en"]="Atziri's Disdain",["flavour"]={["en"]={"They screamed her name in adulation as they gave","their very lives. She looked on with impatience."},["zh"]={"谄媚的他们高呼女王之名，奉献身心。","她却不耐烦地注视着一切。"}},["zh"]="阿兹里的蔑视"},["Atziri's Rule, Reflecting Staff"]={["base"]="Reflecting Staff",["en"]="Atziri's Rule",["flavour"]={["en"]={"Bow before her... or suffer the most gruelling death imaginable."},["zh"]={"跪伏于她，否则就面对最严厉的死亡。"}},["zh"]="阿兹里的统治"},["Atziri's Splendour, Sacrificial Regalia"]={["base"]="Sacrificial Regalia",["en"]="Atziri's Splendour",["flavour"]={["en"]={"\"When you have nothing to hide,","you have nothing to fear.\"","- Atziri, Queen of the Vaal"},["zh"]={"“无愧于心者，","何惧之有？”","——瓦尔女王阿兹里"}},["zh"]="阿兹里的威权"},["Atziri's Step, Cinched Boots"]={["base"]="Cinched Boots",["en"]="Atziri's Step",["flavour"]={["en"]={"\"Those who dance are considered insane","by those who cannot hear the music.\"","- Atziri, Queen of the Vaal"},["zh"]={"“不闻音乐者，","料定跳舞之人皆痴狂。”","——瓦尔女王阿兹里"}},["zh"]="阿兹里的金履"},["Aurseize, Layered Gauntlets"]={["base"]="Layered Gauntlets",["en"]="Aurseize",["flavour"]={["en"]={"Wealth is not to be borne lightly."},["zh"]={"千金万贯，得来不易。"}},["zh"]="富贵之运"},["Beacon of Azis, Solar Amulet"]={["base"]="Solar Amulet",["en"]="Beacon of Azis",["flavour"]={["en"]={"The homeguard signalled for aid against a surprise attack,","but it was not their dekharas that responded.","It was Solerai herself."},["zh"]={"族卫发出了抵抗奇袭的信号，","可回应他们的不是德卡拉，","而是索瑞自己。"}},["zh"]="阿吉斯的道标"},["Beetlebite, Velour Shoes"]={["base"]="Velour Shoes",["en"]="Beetlebite",["flavour"]={["en"]={"They crawl and chitter and swarm","in the shadow of his presence."},["zh"]={"啾鸣的它们蜂拥而至，","尾随着他的影子。"}},["zh"]="甲虫之口"},["Beira's Anguish, Dousing Charm"]={["base"]="Dousing Charm",["effectBlocks"]={{["lines"]={"Immune to Ignite"},["order"]={},["zh"]="免疫点燃"}},["en"]="Beira's Anguish",["flavour"]={["en"]={"They found a crying child tied to a frozen pyre.","She was clad in ice, but the village was ash."},["zh"]={"他们在冰封的火堆上发现了嚎哭的孩子。","她被寒冰紧紧包裹，村庄却已化作燃灰。"}},["zh"]="贝拉的苦楚"},["Belly of the Beast, Explorer Armour"]={["base"]="Explorer Armour",["en"]="Belly of the Beast",["flavour"]={["en"]={"There is no safer place","Than the Belly of the Beast"},["zh"]={"如果你觉得保命奋战太过沉重，","不如就让巨兽吞入腹中。"}},["zh"]="兽腹"},["Berek's Grip, Two-Stone Ring"]={["base"]="Two-Stone Ring",["effectBlocks"]={{["lines"]={"Wind Skills which can be boosted by Elemental Ground Surfaces count","as being boosted by Shocked Ground"},["order"]={},["zh"]="可被元素地面效果加持的风系技能视作 被感电地面加持"}},["en"]="Berek's Grip",["flavour"]={["en"]={"\"Berek hid from Storm's lightning wrath","In the embrace of oblivious Frost","Repelled by ice, blinded by blizzards","Storm raged in vain","While Berek slept.\"","- Berek and the Untamed"},["zh"]={"“贝雷克凌驾风暴之巅，","怀抱一般人只敢远观的雪线；","踏遍冰河，放眼渺无人烟，","深夜狂风恶梦无限，","他竟睡得香甜。”","——贝雷克及抗驯者"}},["zh"]="贝雷克的冰与雷之曲"},["Berek's Pass, Two-Stone Ring"]={["base"]="Two-Stone Ring",["effectBlocks"]={{["lines"]={"Wind Skills which can be boosted by Elemental Ground Surfaces count","as being boosted by Chilled Ground"},["order"]={},["zh"]="可被元素地面效果加持的风系技能视作\n被冰缓地面加持"}},["en"]="Berek's Pass",["flavour"]={["en"]={"\"From Frost's ice-bound pass","Berek taunted and jeered","Until furious Flame scaled the mountain","Berek escaped through the thaw","And Frost's tortured moans.\"","- Berek and the Untamed"},["zh"]={"“贝雷克伫立冰封之道，","对自己征服此地得意逍遥。","那烈炎发出尖啸，","贝雷克却能躲过火烧","以及冷酷的撕咬。”","——贝雷克及抗驯者"}},["zh"]="贝雷克的冰与火之歌"},["Berek's Respite, Two-Stone Ring"]={["base"]="Two-Stone Ring",["effectBlocks"]={{["lines"]={"Wind Skills which can be boosted by Elemental Ground Surfaces count","as being boosted by Ignited Ground"},["order"]={},["zh"]="可被元素地面效果加持的风系技能视作 被点燃地面加持"}},["en"]="Berek's Respite",["flavour"]={["en"]={"\"With Flame licking at his heels","Berek berated the clouds","Until vengeful Storm spewed forth his rains","And Berek held on tight","As Fire screamed and steamed","And fled.\"","- Berek and the Untamed"},["zh"]={"“灾祸的火焰就在脚下翻滚，","贝雷克却充耳不闻；","接着，他感受到雨水划过风暴之后的余温，","于是打起精神，","却感叹自己无法","浴火新生。”","——贝雷克及抗驯者"}},["zh"]="贝雷克的火与雷之乐"},["Beyond Reach, Visceral Quiver"]={["base"]="Visceral Quiver",["en"]="Beyond Reach",["flavour"]={["en"]={"The limit of our knowledge is a barrier","that protects us from ourselves."},["zh"]={"知识的局限是一道屏障，","让我们不被自己所害。"}},["zh"]="望而不及"},["Bijouborne, Double Belt"]={["base"]="Double Belt",["en"]="Bijouborne",["flavour"]={["en"]={"Trifle not with the trinket mage."},["zh"]={"不要招惹饰品法师。"}},["zh"]="珠宝承载者"},["Birth of Fury, Stone Greaves"]={["base"]="Stone Greaves",["en"]="Birth of Fury",["flavour"]={["en"]={"As the sun rises and the light approaches,","so too shall your enemies fear you."},["zh"]={"日出东方，光芒现世，","敌人也将为你胆寒。"}},["zh"]="怒火降生"},["Birthright Buckle, Wide Belt"]={["base"]="Wide Belt",["en"]="Birthright Buckle",["flavour"]={["en"]={"Some families have peculiar gifts..."},["zh"]={"有些家族的礼物属实诡异……"}},["zh"]="天赋扣带"},["Bitterbloom, Feathered Robe"]={["base"]="Feathered Robe",["en"]="Bitterbloom",["flavour"]={["en"]={"The soul cannot flourish in a doubting mind."},["zh"]={"满心疑虑困惑，灵魂便不得滋养。"}},["zh"]="苦涩之花"},["Black Sun Crest, Wrapped Greathelm"]={["base"]="Wrapped Greathelm",["en"]="Black Sun Crest",["flavour"]={["en"]={"The beasts we fear the most","are the ones who dwell in total darkness."},["zh"]={"遁形黑暗之中的猛兽最为让人恐惧。"}},["zh"]="黑阳之冠"},["Blackbraid, Fur Plate"]={["base"]="Fur Plate",["en"]="Blackbraid",["flavour"]={["en"]={"An Ezomyte endures."},["zh"]={"一位艾兹麦人忍辱负重。"}},["zh"]="黑髻"},["Blackflame, Amethyst Ring"]={["base"]="Amethyst Ring",["en"]="Blackflame",["flavour"]={["en"]={"Beyond the veil of death, there burns a fire","by whose light night is borne."},["zh"]={"远在死亡的面纱之外，","燃烧着以黑影为柴的火光。"}},["zh"]="黑焰"},["Blackgleam, Fire Quiver"]={["base"]="Fire Quiver",["en"]="Blackgleam",["flavour"]={["en"]={"Molten feathers, veiled spark,","Hissing arrows from the dark."},["zh"]={"炽羽疾驰化浊影，","烈矢奔腾照光明。"}},["zh"]="黑炎之芒"},["Blackheart, Iron Ring"]={["base"]="Iron Ring",["en"]="Blackheart",["flavour"]={["en"]={"If evil must always exist, so be it.","Embrace it. Become its master."},["zh"]={"若邪恶必将永存，那就接受它。","拥抱它。成为它的主宰。"}},["zh"]="幽暗之语"},["Blessed Bonds, Linen Wraps"]={["base"]="Linen Wraps",["en"]="Blessed Bonds",["flavour"]={["en"]={"\"We survived the endless winter.","We endure the long summer.","One day, spring will return the rains.\""},["zh"]={"“我们熬过了无尽的严冬。","我们挺过了漫长的酷暑。","总有一日，春雨将归来。”"}},["zh"]="蒙福的羁绊"},["Blistering Bond, Ruby Ring"]={["base"]="Ruby Ring",["en"]="Blistering Bond",["flavour"]={["en"]={"\"The Brotherhood of Silence does not set out to torture our targets.","Excruciating pain is simply a byproduct of certain... necessary methods.\""},["zh"]={"“寂静联盟并没有折磨我们的目标。","极致痛苦只是……必要手段的产物。”"}},["zh"]="沸腾桎梏"},["Blood Price, Fierce Greathelm"]={["base"]="Fierce Greathelm",["en"]="Blood Price",["flavour"]={["en"]={"An eye for an eye makes the whole world dead."},["zh"]={"冤冤相报，举目皆亡。"}},["zh"]="血债"},["Blood of the Warrior, Gargantuan Life Flask"]={["base"]="Gargantuan Life Flask",["en"]="Blood of the Warrior",["flavour"]={["en"]={"\"Tukohama may be asleep, but he still gives us his strength. A small","needle, an offering, and a vial... drink deeply, my son, and you","will more than survive the coming battle... you will thrive.\""},["zh"]={"“图克哈马虽然已经沉睡，但依然赐予我们力量。","一枚细针，一次供奉，一瓶圣液……喝下去吧，我的孩子，","你不只能在即将到来的战斗中活下去……你必将凯旋。”"}},["zh"]="战士之血"},["Bloodbarrier, Iron Buckler"]={["base"]="Iron Buckler",["en"]="Bloodbarrier",["flavour"]={["en"]={"A window onto a realm of red,","where countless voices scream..."},["zh"]={"通往赤红领域的窗户，","无数个声音齐声哀嚎……"}},["zh"]="血垒障壁"},["Blueflame Bracers, Goldcast Cuffs"]={["base"]="Goldcast Cuffs",["en"]="Blueflame Bracers",["flavour"]={["en"]={"The secret was lost with its maker."},["zh"]={"它的奥妙已同创造者一起入了土。"}},["zh"]="蓝焰护腕"},["Bones of Ullr, Lattice Sandals"]={["base"]="Lattice Sandals",["en"]="Bones of Ullr",["flavour"]={["en"]={"The dead man walks where","the living fear to tread."},["zh"]={"亡者徘徊之处，","生人退避却步。"}},["zh"]="灵骸之履"},["Brain Rattler, Studded Greatclub"]={["base"]="Studded Greatclub",["en"]="Brain Rattler",["flavour"]={["en"]={"The mind may have no limits, but the skull sure does."},["zh"]={"你的脑力可能没有极限，但你的头颅却不这么认为。"}},["zh"]="脑乱者"},["Bramblejack, Rusted Cuirass"]={["base"]="Rusted Cuirass",["en"]="Bramblejack",["flavour"]={["en"]={"It is safer to be feared than to be loved."},["zh"]={"受人爱戴，不如为人所惧，还比较能保全性命。"}},["zh"]="刺棘宝甲"},["Breath of the Mountains, Sapphire Charm"]={["base"]="Sapphire Charm",["en"]="Breath of the Mountains",["flavour"]={["en"]={"\"To scrape the sky,","to touch the clouds themselves,","is to know true freedom.\"","- Mutewind saying"},["zh"]={"“翱翔天际，","触碰流云，","方知自由为何物。”","— 哑风谚语"}},["zh"]="群山之息"},["Briarpatch, Laced Boots"]={["base"]="Laced Boots",["en"]="Briarpatch",["flavour"]={["en"]={"The druids walk the Grelwood without fear."},["zh"]={"韧木森林中的德鲁伊无所畏惧。"}},["zh"]="荆皮护靴"},["Briskwrap, Rhoahide Coat"]={["base"]="Rhoahide Coat",["en"]="Briskwrap",["flavour"]={["en"]={"\"I carry neither food nor drink. I rely on the charity","of my fellow wayfarers. Dead men are generous men.\"","- Taruk of the Wildmen"},["zh"]={"“我不会前去寻水觅食，","毕竟还有那断了气的同伴遗爱人世。”","——野人塔卢克"}},["zh"]="荒途"},["Bristleboar, Leather Vest"]={["base"]="Leather Vest",["en"]="Bristleboar",["flavour"]={["en"]={"When cornered and desperate, look within for the rage to break loose."},["zh"]={"困入死局而走投无路之时，心中的狂怒仍可助你挣脱。"}},["zh"]="棘体猪肤"},["Bronzebeard, Horned Crown"]={["base"]="Horned Crown",["en"]="Bronzebeard",["flavour"]={["en"]={"Heavy is the head."},["zh"]={"戴冠之人，头重脚轻。"}},["zh"]="青铜须髯"},["Brutus' Lead Sprinkler, Morning Star"]={["base"]="Morning Star",["en"]="Brutus' Lead Sprinkler",["flavour"]={["en"]={"\"A sprinkle of liquid encouragement is often","required to garnish the perfect confession.\"","- Brutus, Warden of Axiom"},["zh"]={"“想要取得招供的最好方法，","就是洒点滚烫的液化金属在罪犯身上。”","— 布鲁特斯，典狱长"}},["zh"]="布鲁特斯的刑具"},["Brynhand's Mark, Wooden Club"]={["base"]="Wooden Club",["en"]="Brynhand's Mark",["flavour"]={["en"]={"The mark of the smith was widely known."},["zh"]={"这位匠人的印记举世皆知。"}},["zh"]="布琳翰德印记"},["Bursting Decay, Unset Ring"]={["base"]="Unset Ring",["en"]="Bursting Decay",["flavour"]={["en"]={"\"All Beidat desires is a foothold, a grip on your flesh,","on the world... he will offer you anything to get it...\"","- Rantings of a Templar prisoner, page thirty"},["zh"]={"“贝达特想要的就是一个立足点，一个抓手，","借此来掌控你的肉体，掌控世界……","为达目的，他会给你一切……”","— 圣堂囚犯的胡言，第三十页"}},["zh"]="腐朽迸发"},["Bushwhack, Lizardscale Boots"]={["base"]="Lizardscale Boots",["en"]="Bushwhack",["flavour"]={["en"]={"Banished for his tragic failure,","Erian learned to hunt to survive."},["zh"]={"悲剧失败，惨遭流放，","阿里安只能以狩猎为生。"}},["zh"]="踏林长靴"},["Byrnabas, Wide Belt"]={["base"]="Wide Belt",["en"]="Byrnabas",["flavour"]={["en"]={"The Brinerot sail without fear of storms."},["zh"]={"布林洛特的水手们不惧风暴。"}},["zh"]="伯纳巴斯"},["Cadiro's Gambit, Primed Quiver"]={["base"]="Primed Quiver",["en"]="Cadiro's Gambit",["flavour"]={["en"]={"\"One can never fully eliminate Chance, but with the right","machinations, all the outcomes may be turned in your favour...\"","- Cadiro Perandus"},["zh"]={"“无论如何抹除，世间总有机遇。","只要机制得当，一切果效都能转为己用……”","——卡迪罗·佩兰德斯"}},["zh"]="卡迪罗的赌局"},["Calgyra's Arc, Ornate Buckler"]={["base"]="Ornate Buckler",["en"]="Calgyra's Arc",["flavour"]={["en"]={"\"There is nowhere my vengeance cannot find you.\""},["zh"]={"“就算逃到天涯海角，也躲不开我的复仇。”"}},["zh"]="凯尔格拉的弧光"},["Call of the Brotherhood, Topaz Ring"]={["base"]="Topaz Ring",["en"]="Call of the Brotherhood",["flavour"]={["en"]={"Forged by three brothers","so that they may recognize each other","across any distance of time or travel."},["zh"]={"此戒由三兄弟合力铸造，即便物换星移，辗转流离，他们终究能以此相认。"}},["zh"]="意志呼唤"},["Candlemaker, Sombre Gloves"]={["base"]="Sombre Gloves",["en"]="Candlemaker",["flavour"]={["en"]={"You can be the wick or the wax. Either way, your light goes out and mine goes on."},["zh"]={"烛芯烛蜡皆一视同仁，火光燃尽助我等光辉。"}},["zh"]="塑烛者"},["Carnage Heart, Amber Amulet"]={["base"]="Amber Amulet",["en"]="Carnage Heart",["flavour"]={["en"]={"Forged from the blood of countless wars,","its thirst has only begun."},["zh"]={"以无数战事的鲜血铸成，","对死亡的饥渴油然而生。"}},["zh"]="屠戮之心"},["Carrion Call, Engraved Focus"]={["base"]="Engraved Focus",["en"]="Carrion Call",["flavour"]={["en"]={"Obedience stretches beyond the grave."},["zh"]={"跨越生命的界限，也将会继续服从。"}},["zh"]="不洁召唤"},["Cat O' Nine Tails, Utility Belt"]={["base"]="Utility Belt",["en"]="Cat O' Nine Tails",["flavour"]={["en"]={"A Templar thinks he's righteous for flogging","himself once for every ten lashings he gives."},["zh"]={"圣堂武僧觉得自己很正义，","因为他每施加十下鞭刑，就会鞭打自己一下。"}},["zh"]="九尾灵猫"},["Chainsting, Hunting Spear"]={["base"]="Hunting Spear",["en"]="Chainsting",["flavour"]={["en"]={"The Sacred Hunt ends with mercy."},["zh"]={"神圣狩猎以仁慈作为终点。"}},["zh"]="缚链之针"},["Chernobog's Pillar, Blacksteel Tower Shield"]={["base"]="Blacksteel Tower Shield",["en"]="Chernobog's Pillar",["flavour"]={["en"]={"Fire dances with those who doubt","Licks the skin and flesh from the fearful","Where there is no fear","There is no flame"},["zh"]={"犹豫迟疑，身陷恶火","胆怯畏惧，皮烧肉灼","唯有无惧无畏","方能业火中自得进退。"}},["zh"]="五芒屏障"},["Chober Chaber, Leaden Greathammer"]={["base"]="Leaden Greathammer",["en"]="Chober Chaber",["flavour"]={["en"]={"The faithful may continue to serve, even after death."},["zh"]={"信众虔诚甚笃，即便死后依旧为神服事。"}},["zh"]="忠诚之锤"},["Choir of the Storm, Jade Amulet"]={["base"]="Jade Amulet",["en"]="Choir of the Storm",["flavour"]={["en"]={"But the fool did not bow.","The fool stood and questioned.","And the fool was unwritten."},["zh"]={"愚人未躬不敬，立于疑惑。","始终他立于疑惑。"}},["zh"]="暴风之语"},["Cloak of Defiance, Havoc Raiment"]={["base"]="Havoc Raiment",["en"]="Cloak of Defiance",["flavour"]={["en"]={"When the throat roars,","As eyes weep,","When the hand grips hard","With trembling fingers,","When belly twists","Yet legs stand strong,","That is the work","Of the Defiant Heart."},["zh"]={"喉咙嘶吼，","双眼泪流，","两手紧握，","十指颤抖，","腹部曲扭，","仍然屹立不休，","问其原因为何?","傲骨绝不屈合。"}},["zh"]="卫道之袍"},["Cloak of Flame, Silk Robe"]={["base"]="Silk Robe",["en"]="Cloak of Flame",["flavour"]={["en"]={"He who sows an ember shall reap an inferno."},["zh"]={"种下燃焰余烬，收割炼狱之炎"}},["zh"]="烈炎之袍"},["Coat of Red, Chain Mail"]={["base"]="Chain Mail",["en"]="Coat of Red",["flavour"]={["en"]={"For those noble families obsessed","with keeping their bloodline pure,","there was a price to pay..."},["zh"]={"高贵家族痴迷于","维护血系的纯粹，","自有代价要偿付……"}},["zh"]="赤红外套"},["Collapsing Horizon, Wyrm Quarterstaff"]={["base"]="Wyrm Quarterstaff",["effectBlocks"]={{["lines"]={"Trigger skills refund half of Energy spent"},["order"]={},["zh"]="触发技能返还消耗能量的一半"}},["en"]="Collapsing Horizon",["flavour"]={["en"]={"The edges bend, the world flexes, the infinite spills into view."},["zh"]={"边界开始扭曲，世界逐渐舒展，永恒映入眼帘。"}},["zh"]="崩塌视界"},["Constricting Command, Viper Cap"]={["base"]="Viper Cap",["en"]="Constricting Command",["flavour"]={["en"]={"\"Be vigilant, Nezahul! When the serpent is cornered, does it give up?","No... It waits. Then it bites the first hand it finds.","The danger of numbers is all in your mind!\"","- Viper Napuatzi, instructing Royal Commander Nezahul"},["zh"]={"“保持警惕，尼札胡！毒蛇被逼入绝境时可会屈服？","不……它会等待时机，咬住眼前出现的第一只手。","你只知势众之危，岂不知困蛇之险！”","——蝰蛇娜帕齐对皇家指挥官尼札胡的训示"}},["zh"]="收缩指令"},["Controlled Metamorphosis, Diamond"]={["base"]="Diamond",["en"]="Controlled Metamorphosis",["flavour"]={["en"]={"Our world was dying, but we chose to survive.","We broke free from the chains within."},["zh"]={"我们的世界奄奄一息，但我们选择活下去。","我们挣脱了内心的枷锁。"}},["zh"]="可控变形"},["Cornathaum, Heavy Crown"]={["base"]="Heavy Crown",["en"]="Cornathaum",["flavour"]={["en"]={"Pain brings clarity."},["zh"]={"身尝苦痛才看得明白。"}},["zh"]="锋锥之帽"},["Corona of the Red Sun, Warrior Greathelm"]={["base"]="Warrior Greathelm",["en"]="Corona of the Red Sun",["flavour"]={["en"]={"Only the High Priests could enact the sacrifices,","but all who witnessed shared in exultation."},["zh"]={"只有高阶祭司能主持奉献仪式，","可所有见证者，都将欣喜若狂。"}},["zh"]="赤红艳阳之冠"},["Corpsewade, Iron Greaves"]={["base"]="Iron Greaves",["en"]="Corpsewade",["flavour"]={["en"]={"Natural decay can be twisted to dark ends."},["zh"]={"自然的衰朽也能成为阴谋的助力。"}},["zh"]="涉灵"},["Cospri's Will, Assassin Garb"]={["base"]="Assassin Garb",["effectBlocks"]={{["lines"]={"Curses you inflict have infinite Duration\nCurses you inflict can affect Hexproof Enemies"},["order"]={},["zh"]="你的诅咒有无限的持续时间\n你的诅咒可以影响无咒的敌人"}},["en"]="Cospri's Will",["flavour"]={["en"]={"Curse their vile Council,","They cast me aside as if I am some bastard child.","If they only knew the power I possess."},["zh"]={"诅咒他们卑劣的议会。","他们把我当成杂种小孩将我排除在外。","他们并不知道我拥有的力量。"}},["zh"]="卡斯普里意志"},["Couture of Crimson, Gilded Vestments"]={["base"]="Gilded Vestments",["en"]="Couture of Crimson",["flavour"]={["en"]={"It is often said of nobles that they live off their","peasants... sometimes, it's truer than any suspect."},["zh"]={"人们常说，贵族是平民百姓头上的吸血鬼。","有些时候……事实确实如此，千真万确。"}},["zh"]="赤红礼装"},["Coward's Legacy, Mail Belt"]={["base"]="Mail Belt",["en"]="Coward's Legacy",["flavour"]={["en"]={"Death is your most important duty.","Face it, or curse your bloodline for all eternity."},["zh"]={"死亡是你的最高职责。","拥抱它，或是为你的血脉降下万世诅咒。"}},["zh"]="懦夫之遗"},["Cracklecreep, Ruby Ring"]={["base"]="Ruby Ring",["en"]="Cracklecreep",["flavour"]={["en"]={"Fear the fire that spreads like a plague."},["zh"]={"蔓如毒疫的烈火，应由人畏之惧之。"}},["zh"]="爆裂蔓延"},["Crest of Ardura, Jingling Crest Shield"]={["base"]="Jingling Crest Shield",["en"]="Crest of Ardura",["flavour"]={["en"]={"When the Red Sekhema called,","the Ardura were the first to answer."},["zh"]={"红色丝克玛高呼之时，","阿杜拉率先前来响应。"}},["zh"]="阿杜拉荣徽"},["Crown of Eyes, Vermeil Circlet"]={["base"]="Vermeil Circlet",["en"]="Crown of Eyes",["flavour"]={["en"]={"Turning, gazing, blinking,","behold the eyes of void.","Burning, razing, drinking,","your mind is destroyed."},["zh"]={"转动，凝视，连连眨眼，","你注视虚幻之眼。","燃烧，夷平，痛饮若狂，","你已经丧心病狂。"}},["zh"]="邪眼之冠"},["Crown of Thorns, Twig Circlet"]={["base"]="Twig Circlet",["en"]="Crown of Thorns",["flavour"]={["en"]={"Lift it lightly, don it slow.","The spikes point out and in, you know."},["zh"]={"轻轻拿起，缓缓戴上。","冠刺锋利，非血即伤。"}},["zh"]="刺棘之冠"},["Crown of the Pale King, Cultist Crown"]={["base"]="Cultist Crown",["en"]="Crown of the Pale King",["flavour"]={["en"]={"A lightless world","a silent reign","two sightless eyes","feed on your pain."},["zh"]={"无光之界，","无声之域，","一双无视线的眼睛，","啃食着你的痛楚。"}},["zh"]="殒皇之冠"},["Crown of the Victor, Iron Crown"]={["base"]="Iron Crown",["en"]="Crown of the Victor",["flavour"]={["en"]={"An endless river of bodies lie in the wake of ambition."},["zh"]={"为酬壮志，万骨皆枯。"}},["zh"]="胜者桂冠"},["Cursecarver, Acrid Wand"]={["base"]="Acrid Wand",["en"]="Cursecarver",["flavour"]={["en"]={"Lost in the Black Fen, Erian hoped that dawn would save him.","He had no idea how far away the light truly was."},["zh"]={"阿里安迷失在黑沼中，只求黎明到来。","他不知道光明究竟降临到了何处。"}},["zh"]="刻咒"},["Daevata's Wind, War Spear"]={["base"]="War Spear",["en"]="Daevata's Wind",["flavour"]={["en"]={"\"You killed their Golden Sekhema. The Maraketh will think of nothing","but vengeance now.\" - Dimos, Advisor to General Titucius"},["zh"]={"“你害死了黄金丝克玛。","现在马拉克斯人唯有复仇这一条路了。”","— 蒂莫斯，提图库斯将军的顾问"}},["zh"]="戴瓦塔的幻风"},["Darkness Enthroned, Fine Belt"]={["base"]="Fine Belt",["en"]="Darkness Enthroned",["flavour"]={["en"]={"Kulemak sat triumphant, raising the crown.","Darkness coiled the world in eternal night.","Victory, a mere moment, came crashing down.","No conqueror, no conquered, only searing Light."},["zh"]={"库勒马克胜利在握，高举王冠。","黑暗将世界拖入永恒长夜。","胜利不过转眼，旋即灰飞烟灭。","没有征服者，没有被征服者，唯有炽烈光辉。"}},["zh"]="夜临"},["Darkray Vectors, Braced Sabatons"]={["base"]="Braced Sabatons",["en"]="Darkray Vectors",["flavour"]={["en"]={"\"Sirrius flew on wings of light, faster than wind, faster","than thought. But try as he might to outrun the darkness,","it was there, at every turn, waiting for him.\"","- Azmerian legend"},["zh"]={"“西里乌斯超越狂风，力振光辉双翼","穿越沉静思绪，在他挑战凌驾黑暗之际，","那暗影总是无所不在，四处迁移。”","——阿兹莫里传说"}},["zh"]="暗雷"},["Death Articulated, Ornate Gauntlets"]={["base"]="Ornate Gauntlets",["en"]="Death Articulated",["flavour"]={["en"]={"\"The mind at the center of the swarm... K'Tash does","the thinking... but it has only one thought... hate.\"","- Rantings of a Templar prisoner, page ninety-four"},["zh"]={"“位居群魔核心的大脑……科塔席负责思考……","但他满脑子只有一种思绪……憎恨。”","— 圣堂囚犯的胡言，第九十四页"}},["zh"]="死神铰链"},["Death Rush, Emerald Ring"]={["base"]="Emerald Ring",["en"]="Death Rush",["flavour"]={["en"]={"To truly appreciate life you must be there when it ends"},["zh"]={"目睹生命的消逝，才能深刻体会存活的价值。"}},["zh"]="亡者呼唤"},["Death's Harp, Dualstring Bow"]={["base"]="Dualstring Bow",["en"]="Death's Harp",["flavour"]={["en"]={"The mournful music of the strings,","The creaking arch, the arrow sings.","A choking cry, a rattled breath,","The Reaper's Song, the Harp of Death."},["zh"]={"万里征途抚弦悼，","号角起，羽矢啸，唯闻百里伤残号；","一世战魂拨琴梢，","生灵息，干戈倒，只望七步亡魂招。"}},["zh"]="冥使之琴"},["Deathblow, Doubled Gauntlets"]={["base"]="Doubled Gauntlets",["en"]="Deathblow",["flavour"]={["en"]={"Anticipation is a gift."},["zh"]={"期盼是一份礼物。"}},["zh"]="死神的袭击"},["Deathrattle, Twig Focus"]={["base"]="Twig Focus",["en"]="Deathrattle",["flavour"]={["en"]={"The cry of death whispers in the wind."},["zh"]={"逝亡者的呼号，化作风中耳语。"}},["zh"]="逝亡呢喃"},["Decree of Acuity, Ancient Visor"]={["base"]="Ancient Visor",["en"]="Decree of Acuity",["flavour"]={["en"]={"\"Focus. Hone your mind. Your lessers rely on the tangible.","Shed your senses, and raze them from this physical realm.\""},["zh"]={"“专注。磨砺你的心智。弱者才依赖有形之物。","剥离你的感官，将他们从这个物质世界彻底抹除。”"}},["zh"]="敏锐法令"},["Decree of Flight, Ancient Leggings"]={["base"]="Ancient Leggings",["en"]="Decree of Flight",["flavour"]={["en"]={"\"Soar. Be swift. Let none trespass here, from","above or below, lest your purpose be forfeit.\""},["zh"]={"“翱翔。迅捷。无论来自天上还是地下，","勿让任何人侵犯此地，以免你的使命前功尽弃。”"}},["zh"]="飞行法令"},["Decree of Loyalty, Ancient Mail"]={["base"]="Ancient Mail",["en"]="Decree of Loyalty",["flavour"]={["en"]={"\"Hold firm. Let no word but the Mothers' turn your head.","Through your unfaltering fealty, you achieve perfection.\""},["zh"]={"“坚守信念。除母神之言，勿让任何话语动摇你心。","凭借坚定不移的忠诚，你方能臻至完美。”"}},["zh"]="忠诚法令"},["Defiance of Destiny, Jade Amulet"]={["base"]="Jade Amulet",["en"]="Defiance of Destiny",["flavour"]={["en"]={"The respect of Karui warriors is hard to earn,","but lasts a lifetime... and beyond."},["zh"]={"卡鲁战士的尊重来之不易，","但会持续一生……乃至身后。"}},["zh"]="命运之抗争"},["Deidbell, Elite Greathelm"]={["base"]="Elite Greathelm",["en"]="Deidbell",["flavour"]={["en"]={"May you never hear it toll."},["zh"]={"希望此钟永不鸣响。"}},["zh"]="丧钟"},["Demon Stitcher, Intricate Gloves"]={["base"]="Intricate Gloves",["en"]="Demon Stitcher",["flavour"]={["en"]={"Xibaqua's treachery was met with divine fury.","One by one, the gods reclaimed their flesh,","until all that remained was a droplet of pure light:","The first Vaal."},["zh"]={"夏巴夸亚的背叛遭到了神罚。","众神逐一剥夺了他们的肉体，","直到他们的身躯只残留下最后一点光沫，","那就是最早的瓦尔。"}},["zh"]="恶魔缝补者"},["Dionadair, Splintered Tower Shield"]={["base"]="Splintered Tower Shield",["en"]="Dionadair",["flavour"]={["en"]={"Praetor Draven knew his only chance to subjugate","the Ezomytes was to catch them unaware."},["zh"]={"执政官德莱文心知肚明，","唯有攻其不备才能征服艾兹麦人。"}},["zh"]="御身守卫"},["Doedre's Damning, Lazuli Ring"]={["base"]="Lazuli Ring",["en"]="Doedre's Damning",["flavour"]={["en"]={"Where her mouth should have been there was only a whirling, black void."},["zh"]={"望向她双颊之间，","徒见那无底深渊。"}},["zh"]="德瑞的魔具"},["Doedre's Tenure, Stitched Gloves"]={["base"]="Stitched Gloves",["en"]="Doedre's Tenure",["flavour"]={["en"]={"While Doedre lacked Maligaro's sense of style,","she surpassed her master in pure malevolence."},["zh"]={"德瑞虽无马雷格罗的才思，","却能善用她天生的毒刺。"}},["zh"]="德瑞的精神手套"},["Doomfletch, Composite Bow"]={["base"]="Composite Bow",["en"]="Doomfletch",["flavour"]={["en"]={"\"Toasted or frozen","Or twitching in the light","I'm not fussy","And neither is Death.\"","- Koralus Doomfletch"},["zh"]={"“尽管劫运当头，饱受苦楚，","吾仅留心于手中把握之物，","如同所招致的死亡般，沉默而专注。”","——“毁灭之弦”寇拉卢斯"}},["zh"]="灭世"},["Doomgate, Braced Tower Shield"]={["base"]="Braced Tower Shield",["en"]="Doomgate",["flavour"]={["en"]={"Welcome to Wraeclast."},["zh"]={"欢迎来到瓦尔克拉斯。"}},["zh"]="毁灭雄关"},["Doryani's Prototype, Scale Mail"]={["base"]="Scale Mail",["en"]="Doryani's Prototype",["flavour"]={["en"]={"\"This was the first step in some grand design,","lost to the ages, now ours to decipher.\"","- Dominus, High Templar"},["zh"]={"宏伟计划终于迈出了第一步，","我们困惑已久，终于取得了进展。","——神主多米纳斯"}},["zh"]="多里亚尼的试作甲"},["Double Vision, Dyad Crossbow"]={["base"]="Dyad Crossbow",["effectBlocks"]={{["lines"]={"When you reload, triggers Gemini Surge to alternately","gain # Cold Surges or # Fire Surges"},["order"]={1,2},["zh"]="当你装填时，触发双灵涌动 交替获得 # 次冰霜涌动或 # 次火焰涌动"}},["en"]="Double Vision",["flavour"]={["en"]={"For those without a home in the Vastiri, the","hot day is harsh, but the chill night is far worse."},["zh"]={"在瓦斯提里无处安居的人们","面对着炎炎白昼，苦寒死夜。"}},["zh"]="双生视界"},["Dreadfist, Bolstered Mitts"]={["base"]="Bolstered Mitts",["en"]="Dreadfist",["flavour"]={["en"]={"What is worse, the sting of the past, the pain of the present, or the fear of the future?"},["zh"]={"最糟糕的，究竟是过去的伤痕，现在的痛苦，还是未来的恐惧？"}},["zh"]="恐惧之拳"},["Dream Fragments, Sapphire Ring"]={["base"]="Sapphire Ring",["en"]="Dream Fragments",["flavour"]={["en"]={"Doryani stumbled into a realm of madness","And awoke its Master."},["zh"]={"多里亚尼误闯狂乱之境，","狂乱帝国之王因其苏醒。"}},["zh"]="梦语之痕"},["Drillneck, Penetrating Quiver"]={["base"]="Penetrating Quiver",["en"]="Drillneck",["flavour"]={["en"]={"\"Why waste such a fine arrow on just one man?\"","- Kiravi, Vaal Archer"},["zh"]={"“何须为这一人耗费如此良箭？”","——瓦尔箭术师奇拉维"}},["zh"]="穿心"},["Duality, Warding Quarterstaff"]={["base"]="Warding Quarterstaff",["en"]="Duality",["flavour"]={["en"]={"Dannig saw Seren in his mind's eye, a public ornament of","extravagance. Until she bore Cadigan a son and vanished.","Decadence covering brutality, like all Kalguuran customs."},["zh"]={"丹宁在脑海中看见塞伦，一个浮夸的公共装饰品。","直到她为卡迪甘生下一个儿子后便消失了。","如同所有卡古兰的习俗，那是用颓废掩盖的暴行。"}},["zh"]="二元一体"},["Dunkelhalt, Leather Buckler"]={["base"]="Leather Buckler",["en"]="Dunkelhalt",["flavour"]={["en"]={"\"A thief in the night, Draven did creep,","families asleep, taken, held on high.","Clever, he thought, 'til his children paid.","Nay, villain, a man never bleeds alone.\""},["zh"]={"“卑鄙的德莱文深夜来袭，","沉睡的人们被俘获受刑。","他自诩聪明却遗祸后代，","谁又能躲避手上的血债。”"}},["zh"]="黑暗止步"},["Dusk Vigil, Ashen Staff"]={["base"]="Ashen Staff",["en"]="Dusk Vigil",["flavour"]={["en"]={"The candlemass tradition was born in a time of darkness and fear."},["zh"]={"做烛火雕像的传统源自于黑暗和恐惧的时代。"}},["zh"]="暮色守望"},["Dustbloom, Studded Vest"]={["base"]="Studded Vest",["en"]="Dustbloom",["flavour"]={["en"]={"Wraeclast has suffered many great disasters,","but life always springs back anew."},["zh"]={"瓦尔克拉斯经历过无数浩劫，","然而生命总能从灰烬中绽放。"}},["zh"]="尘绽"},["Earthbound, Voltaic Staff"]={["base"]="Voltaic Staff",["en"]="Earthbound",["flavour"]={["en"]={"An ancient Azmeri staff, overgrown by roots..."},["zh"]={"上古的阿兹莫里法杖被根须所缠绕……"}},["zh"]="地缚杖"},["Edyrn's Tusks, Iron Cuirass"]={["base"]="Iron Cuirass",["en"]="Edyrn's Tusks",["flavour"]={["en"]={"In death, the legendary boar's tusks were turned","to the slaying of Phaaryl's Eternal oppressors."},["zh"]={"传奇野猪的獠牙化作一把利器","推翻了压迫法瑞欧的永恒之民。"}},["zh"]="艾丁的獠牙"},["Effigy of Cruelty, Antler Focus"]={["base"]="Antler Focus",["en"]="Effigy of Cruelty",["flavour"]={["en"]={"The horrors we imagined as children","still exist somewhere in the dark..."},["zh"]={"儿时想象出的恐魔，","依然潜伏于黑暗中……"}},["zh"]="残酷雕塑"},["Elevore, Hunter Hood"]={["base"]="Hunter Hood",["en"]="Elevore",["flavour"]={["en"]={"Ancient worshippers of the Greatwolf were overtaken","by a ravenous hunger for all things mystical."},["zh"]={"远古的巨狼崇拜者被对所有神秘事物的极度渴望所占据。"}},["zh"]="艾尔弗雷"},["Empire's Grasp, Titan Mitts"]={["base"]="Titan Mitts",["en"]="Empire's Grasp",["flavour"]={["en"]={"\"I like my vassals at sword point,","but my enemies as close as the hilt.\"","- Emperor Chitus"},["zh"]={"“寡人处处提防，就算封臣也得距离一剑之遥，","岂料仇敌宛若剑柄，早已潜伏身旁。”","- 切特斯大帝"}},["zh"]="帝国之掌"},["Enezun's Charge, Volatile Wand"]={["base"]="Volatile Wand",["en"]="Enezun's Charge",["flavour"]={["en"]={"He alone was welcome in the sacred spaces of the Titans."},["zh"]={"泰坦的领域只欢迎他的到来。"}},["zh"]="恩纳尊的职责"},["Enfolding Dawn, Pilgrim Vestments"]={["base"]="Pilgrim Vestments",["en"]="Enfolding Dawn",["flavour"]={["en"]={"The gleam of the night and howling teeth alike could not abate the rising of the sun."},["zh"]={"暗夜无光，利齿嘶嚎，可太阳照常升起。"}},["zh"]="遍洒晨辉"},["Erian's Cobble, Guarded Helm"]={["base"]="Guarded Helm",["en"]="Erian's Cobble",["flavour"]={["en"]={"Sometimes patching up your","equipment gets out of hand."},["zh"]={"有些时候，光是修补行装","也成了一件难于登天之事。"}},["zh"]="阿里安的拼凑"},["Eshtera's Path, Ring"]={["base"]="Ring",["en"]="Eshtera's Path",["flavour"]={["en"]={"During the Winter of the World, her akhara began","shepherding jingakh across the harsh Vastiri. Sekhema","Eshtera planted the seeds of Maraketh diplomacy."},["zh"]={"世界之冬期间，","她的阿卡拉开始引领外来人穿越严酷的瓦斯提里。","丝克玛·埃斯特拉播下了马拉克斯外交的种子。"}},["zh"]="埃斯特拉的道路"},["Essentia Sanguis, Furtive Wraps"]={["base"]="Furtive Wraps",["en"]="Essentia Sanguis",["flavour"]={["en"]={"The darkest clouds clashed and coupled,","giving birth to four lightning children of hate."},["zh"]={"乌云密布，相互碰撞交迭","激发出四道仇恨的雷电。"}},["zh"]="精华收割器"},["Eventide Petals, Veridical Chain"]={["base"]="Veridical Chain",["en"]="Eventide Petals",["flavour"]={["en"]={"Dannig sculpted the Verisium to evoke the","night-blooming lotus of Middengard's stygian peaks,","which grow only where ash meets the snow and stars."},["zh"]={"丹宁雕琢维金，","以唤起米登加德那冥河峰顶的黑夜之莲","——此花仅生于灰烬与雪、星辰交汇之处。"}},["zh"]="黄昏花瓣"},["Evergrasping Ring, Pearl Ring"]={["base"]="Pearl Ring",["en"]="Evergrasping Ring",["flavour"]={["en"]={"Power comes to those who seek","Death comes to those who reach"},["zh"]={"探求者将获得力量，","探取者将寻得灭亡"}},["zh"]="永恒紧缩之戒"},["Eye of Chayula, Gold Amulet"]={["base"]="Gold Amulet",["en"]="Eye of Chayula",["flavour"]={["en"]={"Never blinking, always watching."},["zh"]={"永不眨眼，凝视不休。"}},["zh"]="寻宝者的心眼"},["Eyes of the Runefather, Venerable Defender"]={["base"]="Venerable Defender",["en"]="Eyes of the Runefather",["flavour"]={["en"]={"From aeons past, Dannig felt the Runefather's","gaze, challenging him. There is no honour in ease.","True greatness is torn from the jaws of defeat."},["zh"]={"自远古以来，丹宁便感受到符文之父的目光向他发出挑战。","安逸之中没有荣耀。真正的伟大，","是从失败的血口中夺来的。"}},["zh"]="符父之眼"},["Ezomyte Peak, Soldier Greathelm"]={["base"]="Soldier Greathelm",["en"]="Ezomyte Peak",["flavour"]={["en"]={"Centuries of servitude, a day","of glory, an eternity of death."},["zh"]={"荣华富贵享万日，","过眼烟云又一世。"}},["zh"]="艾兹麦的荣光"},["Facebreaker, Stocky Mitts"]={["base"]="Stocky Mitts",["effectBlocks"]={{["lines"]={"Can Attack as though using a One Handed Mace while both of your hand slots are empty","Unarmed Attacks that would use an Equipped One Hand Mace's damage use this Item's damage"},["order"]={},["zh"]="当你的手部栏位为空时，可视为使用单手锤攻击\n会使用已装备单手锤伤害的徒手攻击将视为使用该物品的伤害"}},["en"]="Facebreaker",["flavour"]={["en"]={"\"You think us savages?\" mused the Red Wolf, as","he pulled teeth from the Eternal's skull. \"I will","show your kind the way of tooth and claw.\""},["zh"]={"“你认为我们是野蛮人？”血狼一边从永恒者的头骨上拔下牙齿，一边沉思道，“我会让你们这类人见识尖牙利爪之道。”"}},["zh"]="毁面者"},["Fairgraves' Curse, Artillery Bow"]={["base"]="Artillery Bow",["en"]="Fairgraves' Curse",["flavour"]={["en"]={"The power of the Allflame rends","souls just as easily as flesh."},["zh"]={"万焚之力撕裂灵魂，","如撕裂血肉那般轻易。"}},["zh"]="费尔的诅咒"},["Feathered Fortress, Crescent Targe"]={["base"]="Crescent Targe",["en"]="Feathered Fortress",["flavour"]={["en"]={"Ride the western wind, and take flight."},["zh"]={"乘西风，翔千里。"}},["zh"]="乱羽金城"},["Fireflower, Solar Amulet"]={["base"]="Solar Amulet",["en"]="Fireflower",["flavour"]={["en"]={"Tale-women in training drink of a painful desert fruit.","Fire, they learn, springs from agony."},["zh"]={"受训的说书人会饮下沙漠之果，","他们这才明白，烈火源于苦痛。"}},["zh"]="烈火繁花"},["Fixation of Yix, Stellar Amulet"]={["base"]="Stellar Amulet",["en"]="Fixation of Yix",["flavour"]={["en"]={"He knew not why he was changing, only","that he wanted to hold his family close..."},["zh"]={"他不知道改变的理由，","只想抱紧自己的家人……"}},["zh"]="伊克斯的专注"},["Flesh Crucible, Diamond"]={["base"]="Diamond",["en"]="Flesh Crucible",["flavour"]={["en"]={"\"Never mind the pain, it's only... making room. Unrelated fact,","a person can live a normal life with just one kidney. Or just one","lung. You never know what Vaal technology will cost you...\""},["zh"]={"“不要在意这疼痛，它不过是在……腾出空间。顺便一提，","人单靠一颗肾或一片肺叶也能正常生活。","你永远不知道瓦尔科技会让你付出什么代价……”"}},["zh"]="血肉玄炉"},["Font of Power, Omen Sceptre"]={["base"]="Omen Sceptre",["effectBlocks"]={{["lines"]={"When a Party Member in your Presence Casts a Spell, you","Sacrifice #% of Mana and they Leech that Mana"},["order"]={1},["zh"]="在场的队伍成员施放法术时，\n你献祭 #% 的魔力并使其偷取等量的魔力"}},["en"]="Font of Power",["flavour"]={["en"]={"Tale-women may not fight directly,","for they have a much higher purpose."},["zh"]={"说书人虽然不舞刀弄剑，","却肩负着更崇高的使命。"}},["zh"]="力量的源泉"},["For Utopia, Stone Charm"]={["base"]="Stone Charm",["effectBlocks"]={{["lines"]={"Cannot be Stunned"},["order"]={},["zh"]="免疫晕眩"}},["en"]="For Utopia",["flavour"]={["en"]={"\"It may be centuries hence, but I still hold utmost faith.","The Saviour will rise, and mankind will be free.\""},["zh"]={"“纵使千秋已逝，我仍怀至深信仰。","救赎者将会崛起，人类将会自由。”"}},["zh"]="为了乌托邦"},["Forbidden Gaze, Chain Tiara"]={["base"]="Chain Tiara",["en"]="Forbidden Gaze",["flavour"]={["en"]={"Keep your heart as ice,","lest your passions stir."},["zh"]={"心中须存冷酷，","莫使情绪激荡。"}},["zh"]="荆棘凝视"},["Forgotten Warden, Primal Markings"]={["base"]="Primal Markings",["en"]="Forgotten Warden",["flavour"]={["en"]={"A gift from the Draíocht, lost in Darkness.","The bronze hums. The cloth sighs.","Living pieces of her, yearning to exist."},["zh"]={"德莱契赠予的礼物，失落于黑暗之中。","青铜嗡鸣，织物叹息。","她是鲜活的碎片，渴求着存在。"}},["zh"]="遗忘守卫"},["Forsaken Bangle, Amethyst Charm"]={["base"]="Amethyst Charm",["en"]="Forsaken Bangle",["flavour"]={["en"]={"Among the Templars, a secret few ate the sins of others.","They bore this burden to empower their hidden Order."},["zh"]={"在圣堂武僧中，少数秘密成员以他人的罪恶为食。","他们负重前行，只为让他们的隐秘教团发展壮大。"}},["zh"]="遗弃手镯"},["Foxshade, Quilted Vest"]={["base"]="Quilted Vest",["en"]="Foxshade",["flavour"]={["en"]={"To catch an animal, think like an animal."},["zh"]={"了解你的猎物，才能驾驭你的猎矛。"}},["zh"]="狐毛铠"},["From Nothing, Diamond"]={["base"]="Diamond",["en"]="From Nothing",["flavour"]={["en"]={"They clawed their way up from the agonising depths of nonexistence,","breathing deep with joy the exquisite light of meaning."},["zh"]={"它们在不曾存在的深渊中挣扎着爬行，","为一缕意义的光辉而欢欣鼓舞。"}},["zh"]="无根之源"},["Frostbreath, Slim Mace"]={["base"]="Slim Mace",["en"]="Frostbreath",["flavour"]={["en"]={"A merciful murderer swept through the streets of Sarn","Robbing breath from the weak and worthless."},["zh"]={"仁慈的罪犯扫过了萨恩的街道","夺走了衰弱和悲哀之人的气息"}},["zh"]="霜息"},["Fury of the King, Ashbark Talisman"]={["base"]="Ashbark Talisman",["en"]="Fury of the King",["flavour"]={["en"]={"Gruthkul was the Mother of Despair...","but one day, the Father will return,","and discover the fate of his children."},["zh"]={"格鲁丝克本是绝望之母……","然终有一日，严父必将归来，","清算子嗣的命运。"}},["zh"]="君王之怒"},["Gamblesprint, Embossed Boots"]={["base"]="Embossed Boots",["en"]="Gamblesprint",["flavour"]={["en"]={"All your tomorrows lie ahead of you,","unknown and snarled to the very last."},["zh"]={"明日未来皆无定，","万般混乱亦未宁。"}},["zh"]="博运步伐"},["Geofri's Sanctuary, Revered Vestments"]={["base"]="Revered Vestments",["en"]="Geofri's Sanctuary",["flavour"]={["en"]={"Faith does not make us invulnerable.","It makes us immortal."},["zh"]={"信念无法让我们刀枪不入","但它却能让我们永不止息"}},["zh"]="吉尔菲的圣殿"},["Ghostmarch, Threaded Shoes"]={["base"]="Threaded Shoes",["en"]="Ghostmarch",["flavour"]={["en"]={"The cursed ones march forever,","On their hopeless, last endeavour."},["zh"]={"受诅亡魂永世行军，","踏上必败无疑的远征。"}},["zh"]="鬼行"},["Ghostwrithe, Tattered Robe"]={["base"]="Tattered Robe",["en"]="Ghostwrithe",["flavour"]={["en"]={"Faith springs abundant at the edge of death."},["zh"]={"信念在死亡的边缘涌现。"}},["zh"]="代笔人"},["Gifts from Above, Prismatic Ring"]={["base"]="Prismatic Ring",["en"]="Gifts from Above",["flavour"]={["en"]={"God blesses those who bless themselves."},["zh"]={"自助而后天助。"}},["zh"]="神赐"},["Glimpse of Chaos, Tribal Mask"]={["base"]="Tribal Mask",["en"]="Glimpse of Chaos",["flavour"]={["en"]={"Man retains sanity and strives toward civilisation","only under the blessed veil of ignorance."},["zh"]={"只有在无知的祝福之下，才能保持理智，心向文明。"}},["zh"]="混沌一瞥"},["Gloamgown, Elementalist Robe"]={["base"]="Elementalist Robe",["en"]="Gloamgown",["flavour"]={["en"]={"The tale-women of old knew how to build anticipation."},["zh"]={"从前的说书人知道如何吊起胃口。"}},["zh"]="薄暮罩袍"},["Gloomform, Waxed Jacket"]={["base"]="Waxed Jacket",["en"]="Gloomform",["flavour"]={["en"]={"It was in this forsaken land, where mists shroud the world in mystery,","that thieves, murderers, and outcasts, sought refuge."},["zh"]={"在这片被遗忘的土地上，迷雾笼罩着世间的奥秘。","宵小、凶犯与浪客寻得了栖身之地。"}},["zh"]="幽邃之躯"},["Glowswarm, Lazuli Ring"]={["base"]="Lazuli Ring",["en"]="Glowswarm",["flavour"]={["en"]={"As their eyes adjusted, they became aware of a strange","blue light. Countless glowing worms crawled above,","blissfully unaware of their flight from the sirens."},["zh"]={"眼目应变，化作古怪的蓝光。","无数闪光的虫子在上方爬行，","丝毫不觉他们从海妖旁逃离。"}},["zh"]="微光虫"},["Goldrim, Felt Cap"]={["base"]="Felt Cap",["en"]="Goldrim",["flavour"]={["en"]={"No metal slips as easily through the fingers as gold."},["zh"]={"凡人的双手总是无法留住最贵重，也是最沉重的资产。"}},["zh"]="金缕帽"},["Goregirdle, Plate Belt"]={["base"]="Plate Belt",["en"]="Goregirdle",["flavour"]={["en"]={"Bleeding just means you're still alive."},["zh"]={"流淌的殷红正是你活着的象征。"}},["zh"]="残血束腰"},["Grand Spectrum, Emerald"]={["base"]="Emerald",["en"]="Grand Spectrum",["flavour"]={["en"]={"An indomitable force of control."},["zh"]={"不屈不折的掌控之力。"}},["zh"]="聚光之石"},["Grand Spectrum, Ruby"]={["base"]="Ruby",["en"]="Grand Spectrum",["flavour"]={["en"]={"A wellspring of vitality bubbling from within."},["zh"]={"从中涌现出生生不息的活力。"}},["zh"]="聚光之石"},["Grand Spectrum, Sapphire"]={["base"]="Sapphire",["en"]="Grand Spectrum",["flavour"]={["en"]={"Skin like steel tempered by bright flames."},["zh"]={"像钢铁在烈火中锻造般的表面。"}},["zh"]="聚光之石"},["Gravebind, Rope Cuffs"]={["base"]="Rope Cuffs",["effectBlocks"]={{["lines"]={"#% increased Rarity of Items found","Your other Modifiers to Rarity of Items found do not apply"},["order"]={1},["zh"]="物品稀有度提高 #%\n你的其他 物品稀有度词缀均不生效"}},["en"]="Gravebind",["flavour"]={["en"]={"Try as you like to hide the","blood on your hands.","You'll still know the truth."},["zh"]={"尽管擦去手上的鲜血吧。","你对此心知肚明。"}},["zh"]="坟场之链"},["Greed's Embrace, Vaal Cuirass"]={["base"]="Vaal Cuirass",["en"]="Greed's Embrace",["flavour"]={["en"]={"Some would question if the risk was worth it.","The rest were already dead."},["zh"]={"有些人会质疑冒这风险是否值得。","其他人则早已死去。"}},["zh"]="贪婪之拥"},["Greymake, Brimmed Helm"]={["base"]="Brimmed Helm",["effectBlocks"]={{["lines"]={"Has # Augment Sockets"},["order"]={1},["zh"]="拥有 # 个增幅器插槽"}},["en"]="Greymake",["flavour"]={["en"]={"In the end, even heroes fade away."},["zh"]={"到头来，英雄豪杰终凋零。"}},["zh"]="苍髯皓首"},["Grip of Kulemak, Abyssal Signet"]={["base"]="Abyssal Signet",["en"]="Grip of Kulemak",["flavour"]={["en"]={"Drink deeply of the Well.","Let the Abyss coil within."},["zh"]={"痛饮魂井之水。","任由深渊在血管中游走。"}},["zh"]="库勒马克之握"},["Grip of Winter, Firm Bracers"]={["base"]="Firm Bracers",["en"]="Grip of Winter",["flavour"]={["en"]={"After the eruption, the skies turned grey,","ash began to fall, and a chill set in..."},["zh"]={"熔火喷发，苍穹黯淡，","飞灰如雪，寒冬降临……"}},["zh"]="凛冬之握"},["Guiding Palm of the Eye, Shrine Sceptre"]={["base"]="Shrine Sceptre",["en"]="Guiding Palm of the Eye",["flavour"]={["en"]={"\"With piercing eyes, you saw through the Stillness.","Undulating as one, you gloriously covered all in white.","But... I can bear you no longer.\"","The Dreamer whispered with fogging breath, ice creeping down his hand."},["zh"]={"“你以锐利目光洞悉寂静。","如波律动，你圣洁覆盖一切白芒。","可是……我无法再承受你。”","幻梦者低语，气息成雾，冰霜自他掌间蔓延。"}},["zh"]="眼目之指引之掌"},["Guiding Palm of the Heart, Shrine Sceptre"]={["base"]="Shrine Sceptre",["en"]="Guiding Palm of the Heart",["flavour"]={["en"]={"\"Power of the Red Pyre! Flaming Heart of the Hive!","I release your burning message to rest here, forevermore.\"","The Dreamer declared, casting out the lingering dark embers within him."},["zh"]={"“赤焰火柱之力！虫巢的烈焰之心！","我释放你炽烈的讯息，让它在此永远安息。”","幻梦者如此宣告，将体内残存的黑暗余烬驱逐出去。"}},["zh"]="心脏之指引之掌"},["Guiding Palm of the Mind, Shrine Sceptre"]={["base"]="Shrine Sceptre",["en"]="Guiding Palm of the Mind",["flavour"]={["en"]={"\"Deep in thought, you would tremble the very air before you.","Wreathed in light, you nurtured them all.","And yet... Your nature became you.\"","The Dreamer mused with aching heart, as remnants of forking tendrils burst forth."},["zh"]={"“你的沉思令空气颤抖。","你光芒四溢抚育众生。","可是……你的本性终成你自身。”","幻梦者哀叹，心痛如绞，分叉的触须残影破体而出。"}},["zh"]="意念之指引之掌"},["Guiding Palm, Shrine Sceptre"]={["base"]="Shrine Sceptre",["en"]="Guiding Palm",["flavour"]={["en"]={"\"When the Third Pact was written in stone, the Dreamer gave the alliance of men and","beasts knowledge. In return, they gave him a drop of blood; one from each of the","races of Wraeclast. In the centuries that followed, his Will began to subtly change.\"","- Book of the Benevolent Dreamer, Histories 220:5"},["zh"]={"“第三契约铭刻于石，幻梦者将智慧赋予人兽联盟。","作为交换，他们献给他一滴血；","来自瓦尔克拉斯每个种族的一滴血。","此后的千百年中，他的意志悄然生变。”","— 《慈爱的幻梦者之书》，编年史220:5"}},["zh"]="指引之掌"},["Hand of Wisdom and Action, Furtive Wraps"]={["base"]="Furtive Wraps",["en"]="Hand of Wisdom and Action",["flavour"]={["en"]={"She thinks and we act.","She acts and we think.","Fragments of the whole that washes clean the skies."},["zh"]={"她的思想，使我们动作。","她的动作，使我们思考。","完整的碎片洗净天空。"}},["zh"]="智行之手"},["Hand of Wisdom and Action, Spiral Wraps"]={["base"]="Spiral Wraps",["en"]="Hand of Wisdom and Action",["flavour"]={["en"]={"She thinks and we act.","She acts and we think.","Fragments of the whole that washes clean the skies."},["zh"]={"她的思想，使我们动作。","她的动作，使我们思考。","完整的碎片洗净天空。"}},["zh"]="智行之手"},["Hateforge, Moulded Mitts"]={["base"]="Moulded Mitts",["en"]="Hateforge",["flavour"]={["en"]={"The first Karui born on the fringes of the Vaal empire developed a blood fever born of corruption."},["zh"]={"首个卡鲁人诞生于瓦尔帝国边陲，","来自一场从腐化中开发血瘟的实验。"}},["zh"]="仇恨熔炉"},["Headhunter, Heavy Belt"]={["base"]="Heavy Belt",["en"]="Headhunter",["flavour"]={["en"]={"\"A man's soul rules from a cavern of bone, learns and","judges through flesh-born windows. The heart is meat.","The head is where the Man is.\"","- Lavianga, Advisor to Kaom"},["zh"]={"“骨骼是灵魂的居所，","血肉是精神和世界交流的窗口，推动一切的力量就在心窝。","即使有了这些，失去了头脑就没有自我。”","——冈姆军师拉维安加"}},["zh"]="猎首"},["Heart of the Well, Diamond"]={["base"]="Diamond",["en"]="Heart of the Well",["flavour"]={["en"]={"Countless souls scream in agonising harmony,","forever sinking under the weight of the newly dead."},["zh"]={"无数魂魄在痛苦中齐声哀嚎，","永远被新亡者的重量压向深渊。"}},["zh"]="泉井之心"},["Heartbound Loop, Pearl Ring"]={["base"]="Pearl Ring",["en"]="Heartbound Loop",["flavour"]={["en"]={"When the axe finally fell, Seryl shared his pain,","and the last thought that flickered through his","fading mind was her broken, shattered scream."},["zh"]={"斧刃落下，塞里尔感受到他的剧痛，","他在恍然垂死时只听见","塞里尔凄厉惨烈的哀嚎。"}},["zh"]="结魂之环"},["Heatshiver, Velvet Cap"]={["base"]="Velvet Cap",["en"]="Heatshiver",["flavour"]={["en"]={"Give of your heated passions.","Give of your cold resolve.","You will be repaid."},["zh"]={"投注炙热感情。","秉持不移坚定。","迎向灿烂光明。"}},["zh"]="寒焰"},["Heroic Tragedy, Timeless Jewel"]={["base"]="Timeless Jewel",["effectBlocks"]={{["lines"]={"Remembrancing # songworthy deeds by the line of Vorana","Passives in radius are Conquered by the Kalguur","Historic"},["order"]={1},["zh"]="纪念 # 件沃拉娜世系值得传唱的事迹 范围内的天赋被卡古兰抑制 史实"},{["lines"]={"Remembrancing # songworthy deeds by the line of Medved","Passives in radius are Conquered by the Kalguur"},["order"]={1},["zh"]="纪念 # 件梅德维德世系值得传唱的事迹\n范围内的天赋被卡古兰抑制"},{["lines"]={"Remembrancing # songworthy deeds by the line of Olroth","Passives in radius are Conquered by the Kalguur"},["order"]={1},["zh"]="纪念 # 件欧罗什世系值得传唱的事迹\n范围内的天赋被卡古兰抑制"}},["en"]="Heroic Tragedy",["flavour"]={["en"]={"They believed themselves courageous and selfless,","but that bravery became the doom at their door."},["zh"]={"他们相信自己的勇敢和无私，","可勇敢成为了通向末日的路。"}},["zh"]="英雄的悲歌"},["Hinekora's Sight, Stellar Amulet"]={["base"]="Stellar Amulet",["en"]="Hinekora's Sight",["flavour"]={["en"]={"Remember the past, anticipate the future."},["zh"]={"回忆过去，预想未来。"}},["zh"]="辛格拉的凝视"},["Hoghunt, Felled Greatclub"]={["base"]="Felled Greatclub",["en"]="Hoghunt",["flavour"]={["en"]={"There was a very clear and delicious","reason why the Ezomytes chose to","stop their flight and settle in Phaaryl."},["zh"]={"艾兹麦人于法瑞欧定居，","漫漫流亡就在此地终结，","源于明显而美味的理由。"}},["zh"]="猎猪大棒"},["Horns of Bynden, Rusted Greathelm"]={["base"]="Rusted Greathelm",["en"]="Horns of Bynden",["flavour"]={["en"]={"The younger brother waded into battle, shrugging off blows."},["zh"]={"弟弟一步步迈向战火，对刀光剑影视而不见。"}},["zh"]="柏安登的犄角"},["Horror's Flight, Engraved Bracers"]={["base"]="Engraved Bracers",["en"]="Horror's Flight",["flavour"]={["en"]={"If fear doesn't kill you, I will."},["zh"]={"如果恐惧杀不死你，我也会亲手杀了你。"}},["zh"]="恐惧之翼"},["Hrimnor's Hymn, Oak Greathammer"]={["base"]="Oak Greathammer",["en"]="Hrimnor's Hymn",["flavour"]={["en"]={"\"The crack of bone, the spray of blood.","Is there sweeter music?\"","- Hrimnor of the Ezomytes."},["zh"]={"“碎骨溅血之声","岂非天籁悦耳之音？”","——艾兹麦人雷姆诺。"}},["zh"]="雷姆诺的夺命凶器"},["Hyrri's Ire, Armoured Vest"]={["base"]="Armoured Vest",["en"]="Hyrri's Ire",["flavour"]={["en"]={"Hyrri loosed a barrage of arrows,","tipped with a poisoned hatred","only oppression can ferment."},["zh"]={"西里的箭雨呼啸而来，","矢锋剧毒命中要害，","留下冰冷遗体诉说悲哀。"}},["zh"]="西里的战衣"},["Hysseg's Claw, Familial Talisman"]={["base"]="Familial Talisman",["en"]="Hysseg's Claw",["flavour"]={["en"]={"In a time of great need, surrounded by Abyssals,","the Wayward Druid came to the Sun Clan's aid.","It is a debt they have never forgotten."},["zh"]={"深渊生物围困的危难之际，","迷途的德鲁伊向烈日部族伸出援手。","这份恩情，族人至今铭记。"}},["zh"]="西赛格之爪"},["Icefang Orbit, Iron Ring"]={["base"]="Iron Ring",["en"]="Icefang Orbit",["flavour"]={["en"]={"Those members of the Brotherhood who employ the venom of","Trarthan ice snakes must take great care with the volatile substance."},["zh"]={"兄弟会的人想要使用特拉珊冰蛇之毒，","那就务必小心谨慎。"}},["zh"]="冰牙指环"},["Icetomb, Mail Vestments"]={["base"]="Mail Vestments",["en"]="Icetomb",["flavour"]={["en"]={"When Solaris closes her burning eye","At the end of time,","the world will perish in ice."},["zh"]={"太阳神阖闭火瞳","时空自此告终，","世界冻亡寒冰之中。"}},["zh"]="冰息"},["Idle Hands, Sectioned Bracers"]={["base"]="Sectioned Bracers",["en"]="Idle Hands",["flavour"]={["en"]={"The devil finds work for idle hands."},["zh"]={"虚度光阴之人容易走上邪道。"}},["zh"]="光阴虚度"},["Idol of Uldurn, Crimson Amulet"]={["base"]="Crimson Amulet",["en"]="Idol of Uldurn",["flavour"]={["en"]={"Worship of house gods was tolerated","in Oriath, so long as it remained private."},["zh"]={"奥瑞亚容忍私下的崇拜，","只是不得将其公之于众。"}},["zh"]="乌尔顿的雕像"},["Igniferis, Crimson Amulet"]={["base"]="Crimson Amulet",["en"]="Igniferis",["flavour"]={["en"]={"A hearth unyielding, ever warm,","A light unbroken, endlessly reborn."},["zh"]={"炉火不灭，温热长存。","光明不惜，复明常恒。"}},["zh"]="燃印"},["Immaculate Adherence, Solar Amulet"]={["base"]="Solar Amulet",["en"]="Immaculate Adherence",["flavour"]={["en"]={"To stray is to condemn this world to sin."},["zh"]={"偏离正道，便是将陷这世界于罪孽之中。"}},["zh"]="完美信条"},["Indigon, Magus Tiara"]={["base"]="Magus Tiara",["en"]="Indigon",["flavour"]={["en"]={"Where the body's limits begin,","the mind's limits end."},["zh"]={"肉体决定了你的起点，","而灵魂决定了你的终点。"}},["zh"]="靛蓝之冠"},["Infernoclasp, Plate Belt"]={["base"]="Plate Belt",["en"]="Infernoclasp",["flavour"]={["en"]={"Tempered by the forbidden flame."},["zh"]={"禁断之火淬炼而出。"}},["zh"]="狱焰之握"},["Ingenuity, Utility Belt"]={["base"]="Utility Belt",["en"]="Ingenuity",["flavour"]={["en"]={"Experiments with geomancy taught","the Maji more than they ever expected."},["zh"]={"众贤尝试地术，","收获远超预想。"}},["zh"]="奇思妙想"},["Innsmouth, Shabby Hood"]={["base"]="Shabby Hood",["en"]="Innsmouth",["flavour"]={["en"]={"Beyond madness lies inspiration."},["zh"]={"灵感埋没在疯狂的另一端。"}},["zh"]="印斯茅斯"},["Ironbound, Warden Bow"]={["base"]="Warden Bow",["en"]="Ironbound",["flavour"]={["en"]={"Each crest was a Thane's word, bolted to Ivor's bow.","They would join the Count's side, or die by his hands."},["zh"]={"每一枚纹章都是一位领主的誓约，被铆接在艾沃的弓上。他们要么归顺伯爵，要么死于伯爵之手。"}},["zh"]="铁箍战弓"},["Irongrasp, Vagabond Armour"]={["base"]="Vagabond Armour",["en"]="Irongrasp",["flavour"]={["en"]={"A power unknown aids your own."},["zh"]={"那股未知的力量也为你所用。"}},["zh"]="铁腕"},["Ironride, Visored Helm"]={["base"]="Visored Helm",["en"]="Ironride",["flavour"]={["en"]={"Let the rider's aim be true."},["zh"]={"愿骑手能百发百中。"}},["zh"]="铁驭"},["Jarngreipr, Ringmail Gauntlets"]={["base"]="Ringmail Gauntlets",["en"]="Jarngreipr",["flavour"]={["en"]={"The whispers of the old gods hum through the iron. They demand a hero."},["zh"]={"旧神的低语在铁中嗡嗡作响。他们呼唤英雄到来。"}},["zh"]="金石手甲"},["Kalandra's Touch, Ring"]={["base"]="Ring",["en"]="Kalandra's Touch",["flavour"]={["en"]={"Power is a matter of perspective."},["zh"]={"力量也只是一种观念。"}},["zh"]="卡兰德之触"},["Kaltenhalt, Ridged Buckler"]={["base"]="Ridged Buckler",["en"]="Kaltenhalt",["flavour"]={["en"]={"Cold, miserable and alone... but alive."},["zh"]={"冰冷，悲惨，无人过问，但一息尚存。"}},["zh"]="冰霜之镜"},["Kaom's Heart, Conqueror Plate"]={["base"]="Conqueror Plate",["en"]="Kaom's Heart",["flavour"]={["en"]={"The warrior who fears will fall."},["zh"]={"勇斗之魂无坚不摧，","懦弱之心退缩避畏。"}},["zh"]="冈姆的壮志"},["Keelhaul, Linen Belt"]={["base"]="Linen Belt",["en"]="Keelhaul",["flavour"]={["en"]={"Below all living things,","there exists a flow..."},["zh"]={"众生之下，","皆有涓流……"}},["zh"]="罪罚拖绳"},["Keeper of the Arc, Spiritbone Crown"]={["base"]="Spiritbone Crown",["effectBlocks"]={{["lines"]={"Alternating every 5 seconds:","Take #% less Damage from Hits","Take #% less Damage over time"},["order"]={1,2},["zh"]="每 5 秒交替： 受到的击中伤害总降 #% 受到的持续伤害总降 #%"}},["en"]="Keeper of the Arc",["flavour"]={["en"]={"The priests of the Kalguur keep faith through numbers","and calculation, not unprovable promises."},["zh"]={"卡古兰的先师相信数字和计算，","而不是无从求证的空洞诺言。"}},["zh"]="弧光守护者"},["Killjoy, Linen Wraps"]={["base"]="Linen Wraps",["en"]="Killjoy",["flavour"]={["en"]={"\"Stitches? Wouldn't that defeat the purpose?\"","- Jeffry, Torturer's Apprentice"},["zh"]={"缝起来？那不就违背本意了吗？","——杰弗里，拷问者的学徒"}},["zh"]="败兴灾星"},["Kingsguard, Full Plate"]={["base"]="Full Plate",["en"]="Kingsguard",["flavour"]={["en"]={"The toughest armour is the trust of your people."},["zh"]={"信任你的人民将成为你最坚固的护具。"}},["zh"]="皇家卫甲"},["Kitoko's Current, Jewelled Gloves"]={["base"]="Jewelled Gloves",["en"]="Kitoko's Current",["flavour"]={["en"]={"Reality is a puzzle. Ingenuity is power."},["zh"]={"现实如同谜题，才思乃是力量。"}},["zh"]="奇托克的洪流"},["Lavianga's Spirits, Gargantuan Mana Flask"]={["base"]="Gargantuan Mana Flask",["en"]="Lavianga's Spirits",["flavour"]={["en"]={"\"How do I cope with what I witnessed on Wraeclast?","Thank the Ancestors! My cup, it overflows.\"","- Lavianga, former advisor to Kaom"},["zh"]={"“我该如何面对在瓦尔克拉斯目睹的一切？","感谢先祖！我的酒杯，早已满溢。”","— 拉维安加，冈姆前任军师"}},["zh"]="拉维安加之灵"},["Leer Cast, Hooded Mask"]={["base"]="Hooded Mask",["en"]="Leer Cast",["flavour"]={["en"]={"For none of us are as cruel as all of us."},["zh"]={"结群聚众必然生成力量之源。"}},["zh"]="共鸣之面"},["Legionstride, Rough Greaves"]={["base"]="Rough Greaves",["en"]="Legionstride",["flavour"]={["en"]={"A wall of steel and muscle."},["zh"]={"坚钢与血肉铸成了长城。"}},["zh"]="军团的进击"},["Leopold's Applause, Embroidered Gloves"]={["base"]="Embroidered Gloves",["en"]="Leopold's Applause",["flavour"]={["en"]={"\"Keep smiling. The deepest cut comes not from insults, but from false praise.\""},["zh"]={"“接着微笑吧。最深的伤痕并非来自侮辱，而是源于虚伪的赞美。”"}},["zh"]="利奥波德的赞许"},["Levinstone, Topaz Ring"]={["base"]="Topaz Ring",["en"]="Levinstone",["flavour"]={["en"]={"Highgate held other secrets."},["zh"]={"统治者之殿还隐藏着其他秘密。"}},["zh"]="电光之石"},["Lifesprig, Attuned Wand"]={["base"]="Attuned Wand",["en"]="Lifesprig",["flavour"]={["en"]={"From the smallest seeds","To the tallest redwoods,","Life endures in Wraeclast."},["zh"]={"至微者，须弥芥子","至伟者，参天神木，","无论微伟，皆可立足帝陆。"}},["zh"]="生机之记"},["Lightning Coil, Ancestral Mail"]={["base"]="Ancestral Mail",["en"]="Lightning Coil",["flavour"]={["en"]={"The world churned during the Great Wasting.","Tawhoa may have stilled the rioting earth,","but it was Valako that tamed the broken sky."},["zh"]={"大荒废年代里，世界天翻地覆。","塔赫亚也许能安抚狂暴的大地，","但能制服破碎天穹的只有瓦拉克。"}},["zh"]="雷语"},["Ligurium Talisman, Lapis Amulet"]={["base"]="Lapis Amulet",["en"]="Ligurium Talisman",["flavour"]={["en"]={"Healing the soul requires sacrifice."},["zh"]={"只有精诚奉献，才能治愈心灵。"}},["zh"]="猞利子护符"},["Liminal Coil, Twisted Wand"]={["base"]="Twisted Wand",["effectBlocks"]={{["lines"]={"Magnitudes of Curses you inflict are zero"},["order"]={},["zh"]="你造成的诅咒强度为零"}},["en"]="Liminal Coil",["flavour"]={["en"]={"In that moment, Viridi's bones became","branches, weaving over the Darkness.","She coiled around the nothing,","trapping it within her everything."},["zh"]={"那一刻，维里迪的骸骨化作枝杈，","在黑暗之上编织。","她盘绕虚空，","将其困于自身的万物之中。"}},["zh"]="阈限螺旋"},["Lioneye's Glare, Heavy Bow"]={["base"]="Heavy Bow",["effectBlocks"]={{["lines"]={"# metres to Dodge Roll distance if you haven't Dodge Rolled Recently","# metre to Dodge Roll distance if you've Dodge Rolled Recently"},["order"]={1,2},["zh"]="若你近期未进行闪避翻滚，闪避翻滚距离 +# 米 若你近期进行闪避翻滚，闪避翻滚距离 # 米"}},["en"]="Lioneye's Glare",["flavour"]={["en"]={"\"Kinslayer, you dishonour your own traditions to turn the tide of battle!","Let us see which is stronger... Karui savagery or the might of the Empire!\"","- General Marceus Lioneye"},["zh"]={"“弑亲者，你为扭转战局，居然背弃传统！","让我们看看哪方更强……卡鲁的野性，还是帝国的力量！”","— 穆希尔斯，狮眼将军"}},["zh"]="狮眼的战弓"},["Lochtonial Caress, Tempered Mitts"]={["base"]="Tempered Mitts",["en"]="Lochtonial Caress",["flavour"]={["en"]={"Why cling to your sanity? It offers you nothing.","Surrender to me, and I will grant you everything."},["zh"]={"迁就理智，你将一无所获，","屈服于我，你将收获丰硕。"}},["zh"]="意识之缘"},["Loreweave, Ornate Ringmail"]={["base"]="Ornate Ringmail",["en"]="Loreweave",["flavour"]={["en"]={"The collector need not even speak. Each ring","regaled them with tales of his conquest."},["zh"]={"收藏家甚至无需开口。","每枚戒指都向他讲述着他的征服传奇。"}},["zh"]="满溢之甲"},["Luminous Pace, Straw Sandals"]={["base"]="Straw Sandals",["en"]="Luminous Pace",["flavour"]={["en"]={"Blessed are those who tend the Grove."},["zh"]={"护林之人可蒙恩典。"}},["zh"]="流光步履"},["Lycosidae, Rampart Tower Shield"]={["base"]="Rampart Tower Shield",["en"]="Lycosidae",["flavour"]={["en"]={"A true predator does not chase; It waits."},["zh"]={"真正的狩猎者不会追逐；只会等待。"}},["zh"]="狼蛛"},["Mageblood, Utility Belt"]={["base"]="Utility Belt",["en"]="Mageblood",["flavour"]={["en"]={"Rivers of power coursed through their veins.","Now, that power is yours, for good or ill."},["zh"]={"力量的河流曾于他们血管中奔涌。","如今，那力量属于你了——无论祸福。"}},["zh"]="法师之血"},["Mahuxotl's Machination, Omen Crest Shield"]={["base"]="Omen Crest Shield",["en"]="Mahuxotl's Machination",["flavour"]={["en"]={"The Banished Architect sought to employ the darkest secrets of the Vaal."},["zh"]={"被放逐的建筑师试图采用最黑暗的瓦尔秘法。"}},["zh"]="马赫索托之诈"},["Maligaro's Virtuosity, Fine Bracers"]={["base"]="Fine Bracers",["en"]="Maligaro's Virtuosity",["flavour"]={["en"]={"Maligaro operated effortlessly,","with great speed and terrible consequences."},["zh"]={"马雷格罗奇术出众卓越，","无比迅捷，带来无尽浩劫。"}},["zh"]="马雷格罗的玫红手套"},["Marohi Erqi, Totemic Greatclub"]={["base"]="Totemic Greatclub",["en"]="Marohi Erqi",["flavour"]={["en"]={"\"Drunken Erqi boasted to Tukohama; the God of War","challenged him to a clash of strength. Woe to the","Divine - he should have made it a test of skill!\""},["zh"]={"“醉汉厄尔齐跟图克哈马吹牛；","战神跟他比拼力气。倒霉的是神明","——他应该比的是技巧才对！”"}},["zh"]="尔奇的巨灵之锤"},["Mask of the Sanguimancer, Face Mask"]={["base"]="Face Mask",["en"]="Mask of the Sanguimancer",["flavour"]={["en"]={"A terror of ancient times, his identity","remains lost... but his power does not."},["zh"]={"那上古恐魔的身份无人知晓，","可他的力量并未失落。"}},["zh"]="血咒师面罩"},["Mask of the Stitched Demon, Feathered Tiara"]={["base"]="Feathered Tiara",["en"]="Mask of the Stitched Demon",["flavour"]={["en"]={"From the flesh of the gods, Xibaqua was born.","From the carnage of Xibaqua, we were born.","It is our duty to return to the gods what was once theirs."},["zh"]={"夏巴夸亚源于众神之躯。","而我们则生于它的遗骸。","那么，归于众神自然是吾等之大限。"}},["zh"]="缝合恶魔面罩"},["Matsya, Crescent Quarterstaff"]={["base"]="Crescent Quarterstaff",["en"]="Matsya",["flavour"]={["en"]={"In our tales, and in our hearts, the rivers still flow."},["zh"]={"传于故事，藏于内心，河川奔流不止。"}},["zh"]="摩蹉"},["Megalomaniac, Diamond"]={["base"]="Diamond",["en"]="Megalomaniac",["flavour"]={["en"]={"If you're going to act like you're better","than everyone else, make sure you are."},["zh"]={"如果你想表现得比所有人都强，","那最好有真本事。"}},["zh"]="妄想症"},["Meginord's Girdle, Rawhide Belt"]={["base"]="Rawhide Belt",["en"]="Meginord's Girdle",["flavour"]={["en"]={"Kaom's strength was rivaled only by","the great Meginord of the north."},["zh"]={"冈姆的勇猛威震天下，","唯有北方的梅吉诺德能与他一较高下。"}},["zh"]="梅吉诺德的力量泉源"},["Melting Maelstrom, Ultimate Mana Flask"]={["base"]="Ultimate Mana Flask",["en"]="Melting Maelstrom",["flavour"]={["en"]={"What is life, but a dreamlike spiral of panic?"},["zh"]={"所谓生命，不就是噩梦般螺旋不止的恐慌吗？"}},["zh"]="消融漩涡"},["Merit of Service, Pelage Targe"]={["base"]="Pelage Targe",["en"]="Merit of Service",["flavour"]={["en"]={"Lead by example, and you shall never be alone."},["zh"]={"以身作则，就不会成为孤身陌客。"}},["zh"]="奉献的犒赏"},["Midnight Braid, Rawhide Belt"]={["base"]="Rawhide Belt",["en"]="Midnight Braid",["flavour"]={["en"]={"Adversity is the soil in","which persistence grows."},["zh"]={"以逆境为沃土，","便可培育毅力。"}},["zh"]="午夜穗带"},["Mind of the Council, Death Mask"]={["base"]="Death Mask",["en"]="Mind of the Council",["flavour"]={["en"]={"The sky tore asunder, black cleaving upon blue","The end of life, of Time, with no escape","But they found a fragment, a void, a haven","And there they waited, as it all began again","Dark will, dark knowledge, enemies of Fate","They know your mind, because they remember"},["zh"]={"天空撕裂，漆黑破空，","生命终结，时间终末，无处可逃。","他们却找到碎片、虚空与避所，","就在那里，等待一切再度开始。","黑暗的意志，黑暗的知识，命运的敌人：","他们知你之念，因为他们曾记得。"}},["zh"]="智者之秘"},["Ming's Heart, Amethyst Ring"]={["base"]="Amethyst Ring",["en"]="Ming's Heart",["flavour"]={["en"]={"Ming slew Tranquillity","Took Chaos for his wife","And on Her immortal finger","He placed his Heart"},["zh"]={"明将宁静击毙","迎娶混沌为妻","在她那不朽的细指","明戴上真心诚挚"}},["zh"]="明恩的慧心"},["Mist Whisper, Makeshift Crossbow"]={["base"]="Makeshift Crossbow",["en"]="Mist Whisper",["flavour"]={["en"]={"Sibilant promises surrounded them in the night.","All the travelers had to give him was their devotion..."},["zh"]={"深夜之际，细碎的承诺环绕着他们。","所有旅人只得向他献出自己的虔诚。"}},["zh"]="迷雾低语者"},["Mjolner, Torment Club"]={["base"]="Torment Club",["en"]="Mjolner",["flavour"]={["en"]={"Look the storm in the eye and you will have its respect."},["zh"]={"拾起此锤者，将可操控雷霆，号令风暴。"}},["zh"]="沉默之雷"},["Morior Invictus, Grand Regalia"]={["base"]="Grand Regalia",["en"]="Morior Invictus",["flavour"]={["en"]={"The Unblinking Eye did not cower and wail.","They stood against the end."},["zh"]={"凝望之眼绝不会退缩，","他们傲立至最后一刻。"}},["zh"]="无生之辱"},["Murkshaft, Toxic Quiver"]={["base"]="Toxic Quiver",["en"]="Murkshaft",["flavour"]={["en"]={"\"Boiling frogs isn't for spells, dear. That's a disgusting","rumour. They're actually for brewing poisons.\"","- Selassie of the Black Fen"},["zh"]={"“水煮青蛙不是为了施法，亲爱的。那是","歹毒的谣传。这其实是用来制备毒药的。”","——黑沼的瑟莱西"}},["zh"]="沉郁之棍"},["Myris Uxor, Covert Hood"]={["base"]="Covert Hood",["en"]="Myris Uxor",["flavour"]={["en"]={"The end always comes sooner than we think."},["zh"]={"结局近在眼前，远超你我所想。"}},["zh"]="迈里斯之妇"},["Nascent Hope, Thawing Charm"]={["base"]="Thawing Charm",["effectBlocks"]={{["lines"]={"Immune to Freeze"},["order"]={},["zh"]="免疫冻结"}},["en"]="Nascent Hope",["flavour"]={["en"]={"\"Even in the face of the Winter of the World,","life found a way. The Spirit always provides.\""},["zh"]={"“即使面对世界之冬，生命也能找到出路。","万灵始终都在庇佑我们。”"}},["zh"]="新生希望"},["Nazir's Judgement, Steelpoint Quarterstaff"]={["base"]="Steelpoint Quarterstaff",["en"]="Nazir's Judgement",["flavour"]={["en"]={"The first witch hunter knew one critical tactic:","never let your enemy have a clear moment."},["zh"]={"最初的猎巫人掌握了最重要的战术：","绝不可让你的敌人获得片刻的安生。"}},["zh"]="纳吉尔的审判"},["Nebuloch, Brigand Mace"]={["base"]="Brigand Mace",["en"]="Nebuloch",["flavour"]={["en"]={"They hoped that, trapped in its prison,","the creature would age and perish.","But time would not touch the fiend."},["zh"]={"人们希望，那只被困在牢狱中的怪物","会衰老死去。","但时间没有对这只恶魔造成丝毫影响。"}},["zh"]="尼布洛克"},["Necromantle, Bone Raiment"]={["base"]="Bone Raiment",["en"]="Necromantle",["flavour"]={["en"]={"Fueled by the blackness in the hearts of men,","the armies of Saresh were just as relentless."},["zh"]={"沙利希的无穷大军冷酷无情，","人心的黑暗助长了那份气焰。"}},["zh"]="通灵披风"},["Ngamahu's Chosen, Ruby Charm"]={["base"]="Ruby Charm",["en"]="Ngamahu's Chosen",["flavour"]={["en"]={"Kaom was not known for his restraint."},["zh"]={"冈姆的英名与隐忍毫无关联。"}},["zh"]="努葛玛呼的亲选"},["Nightfall, Fortress Tower Shield"]={["base"]="Fortress Tower Shield",["en"]="Nightfall",["flavour"]={["en"]={"\"Upon plains of endless chill,","They Who Never Tire... dominate.","They Who Never Surrender... terrify.","And They Who Lay Beneath... wait for Nightfall.\"","- Tul, She That Silences"},["zh"]={"“于无尽寒原之上，","永不疲倦者……主宰。","永不降者……令人生畏。","而蛰伏于下者……静候夜幕降临。”","— 托沃，止息之母"}},["zh"]="夜临"},["Nightscale, Pauascale Gloves"]={["base"]="Pauascale Gloves",["en"]="Nightscale",["flavour"]={["en"]={"Diamora sings not for hunger, but for longing."},["zh"]={"驱使戴娅摩菈歌唱的不是饥饿，而是渴求。"}},["zh"]="夜鳞"},["Nocturne, Wooden Buckler"]={["base"]="Wooden Buckler",["en"]="Nocturne",["flavour"]={["en"]={"Light and shadow chase eternal,","but neither knows the other exists..."},["zh"]={"光影在永恒的追逐中纠缠，","却根本不知道彼此的存在。"}},["zh"]="夜曲"},["Northpaw, Suede Bracers"]={["base"]="Suede Bracers",["en"]="Northpaw",["flavour"]={["en"]={"Fight with the ferocity of the First Ones."},["zh"]={"上阵搏杀的英姿，当如凶猛的初生之子。"}},["zh"]="北境凶爪"},["Oaksworn, Sigil Crest Shield"]={["base"]="Sigil Crest Shield",["en"]="Oaksworn",["flavour"]={["en"]={"The druids swore to protect the Grelwood with their very lives."},["zh"]={"德鲁伊誓言守护韧木森林，不惜生命。"}},["zh"]="橡木盟誓"},["Obern's Bastion, Stacked Sabatons"]={["base"]="Stacked Sabatons",["en"]="Obern's Bastion",["flavour"]={["en"]={"The storm cannot sway those of sure footing."},["zh"]={"稳健之人无惧风浪。"}},["zh"]="欧本的壁垒"},["Olroth's Resolve, Ultimate Life Flask"]={["base"]="Ultimate Life Flask",["en"]="Olroth's Resolve",["flavour"]={["en"]={"Olroth the Gallant,","tireless and true,","he fights for me,","he fights for you!"},["zh"]={"勇敢的欧罗什，","不知疲倦和真实，","他为我而战，","他为你而战！"}},["zh"]="欧罗什的决心"},["Olrovasara, Torment Club"]={["base"]="Torment Club",["effectBlocks"]={{["lines"]={"On Hitting an enemy, gains maximum added Lightning damage equal to","the enemy's Power for 20 seconds, up to a total of #"},["order"]={1},["zh"]="击中敌人时，获得相当于敌人威力值的\n额外闪电伤害上限，最多 #，持续 20 秒"}},["en"]="Olrovasara",["flavour"]={["en"]={"\"True heroes grow stronger in the face of adversity.\"","- Fourth Tenet of the Knights of the Sun"},["zh"]={"“真正的英雄面对逆境，越挫越勇。”","— 《烈阳骑士第四信条》"}},["zh"]="欧罗瓦萨拉"},["Opportunity, Ultimate Life Flask"]={["base"]="Ultimate Life Flask",["en"]="Opportunity",["flavour"]={["en"]={"\"Calculations complete, and He is assembled.","Our immaculate tactics are set in motion.\""},["zh"]={"“计算完毕，他已组装完成。","我们的完美战术已启动。”"}},["zh"]="机遇"},["Original Sin, Amethyst Ring"]={["base"]="Amethyst Ring",["en"]="Original Sin",["flavour"]={["en"]={"Innocence rose to godhood not on inspired faith,","but on the vilification and hatred of another."},["zh"]={"纯净之神升格成为神灵并不是靠信仰所激发，","而是对另外一个人的诋毁和憎恨。"}},["zh"]="原初之罪"},["Painter's Servant, Torn Gloves"]={["base"]="Torn Gloves",["en"]="Painter's Servant",["flavour"]={["en"]={"Bloodshed on the crimson shores,","longing for the endless sea.","Treasures, life, I'd give it all","just to capture thee."},["zh"]={"猩红海岸血战殇，","唯盼无尽之汪洋。","珍宝生命皆可献，","只求跃然笔墨间。"}},["zh"]="画师之侍"},["Palm of the Dreamer, Shrine Sceptre"]={["base"]="Shrine Sceptre",["en"]="Palm of the Dreamer",["flavour"]={["en"]={"\"We sometimes fail. We sometimes succeed. Who determines one from the other?","I now know we can never be made One, if we are bore of differing desires.","And yet, I have hope for a new truth. And I will see it... made real.\"","- The Benevolent Dreamer"},["zh"]={"“我们有时失败，有时成功。谁来定义孰是孰非？","我如今明白：若我们欲合为一体，却心怀不同愿望，便永不得其所。","但我依然怀抱希望，愿这新真理……得以实现。”","— 慈爱的幻梦者"}},["zh"]="幻梦者之掌"},["Pariah's Embrace, Cloaked Mail"]={["base"]="Cloaked Mail",["en"]="Pariah's Embrace",["flavour"]={["en"]={"His isolation caused him to treasure","their companionship all the more."},["zh"]={"正是因为他向来孑然一身，","才会如此珍视他们的陪伴。"}},["zh"]="贱民之拥"},["Perandus Seal, Gold Ring"]={["base"]="Gold Ring",["en"]="Perandus Seal",["flavour"]={["en"]={"A pact with Prospero always comes at a price."},["zh"]={"与普洛斯彼罗定约总要付出代价。"}},["zh"]="普兰德斯的印章"},["Perfidy, Knight Armour"]={["base"]="Knight Armour",["en"]="Perfidy",["flavour"]={["en"]={"The Trickster God turned the very Day and Night against each other.","What hope have you?"},["zh"]={"狡诈的天神让白昼和夜晚永世为敌，","你还能有什么指望？"}},["zh"]="背信弃义"},["Periphery, Heartwood Shortbow"]={["base"]="Heartwood Shortbow",["en"]="Periphery",["flavour"]={["en"]={"As the Maji approached the edge of Nothingness, she strung","fragments of the Wildwood's carcass together. When she","nocked her arrow, she pulled upon the elements of life itself."},["zh"]={"当玛吉行至虚无之畔，","她将荒林残骸的碎片串联成弓。","当她搭箭上弦，她引动的便是生命本身的元素。"}},["zh"]="边缘"},["Pillar of the Caged God, Long Quarterstaff"]={["base"]="Long Quarterstaff",["en"]="Pillar of the Caged God",["flavour"]={["en"]={"Forged to rule the waves and tide","Destined to serve the monkey's paw","Strong as a tower of iron","Deft as the needle doubt"},["zh"]={"生来驾浪驭潮","命定侍从行者","若铁塔，坚韧不倒","似细针，挥动自如"}},["zh"]="囚神杵"},["Plaguefinger, Gauze Wraps"]={["base"]="Gauze Wraps",["en"]="Plaguefinger",["flavour"]={["en"]={"Ulcers, scabs, and pocks, the third army makes its claim."},["zh"]={"溃疡、痂痕和痘疹，索命无数的第三方。"}},["zh"]="毒疫之指"},["Polcirkeln, Sapphire Ring"]={["base"]="Sapphire Ring",["en"]="Polcirkeln",["flavour"]={["en"]={"I rule the north","A legacy earned","Time and time again","Sing Meginord's song!"},["zh"]={"我御北疆之地，","争得一世传承，","梅吉诺德之歌，","传唱千秋万代！"}},["zh"]="极圈"},["Powertread, Hunting Shoes"]={["base"]="Hunting Shoes",["en"]="Powertread",["flavour"]={["en"]={"The combat stance used by Vaal nobles","was as elegant as it was deadly."},["zh"]={"瓦尔贵族的战姿","优雅与致命相伴。"}},["zh"]="神力靴"},["Pragmatism, Explorer Armour"]={["base"]="Explorer Armour",["en"]="Pragmatism",["flavour"]={["en"]={"In an endless war against darkness,","one must be ever vigilant."},["zh"]={"在对抗黑暗的无尽战争里，","每个人都要时刻警惕。"}},["zh"]="独断专行"},["Prayers for Rain, Keth Raiment"]={["base"]="Keth Raiment",["en"]="Prayers for Rain",["flavour"]={["en"]={"In its final era, the roofs of Keth were rife with","anything and everything that could hold water...","should the opportunity arise."},["zh"]={"在最后的那个时代","克斯的屋顶摆满了盛水的器皿……","只求那一丝生机。"}},["zh"]="祈雨祷告"},["Prism Guardian, Sectarian Crest Shield"]={["base"]="Sectarian Crest Shield",["en"]="Prism Guardian",["flavour"]={["en"]={"When blood is paid, the weak think twice."},["zh"]={"唯有弱者对挥洒鲜血感到迟疑。"}},["zh"]="元素的庇护"},["Prism of Belief, Diamond"]={["base"]="Diamond",["en"]="Prism of Belief",["flavour"]={["en"]={"Entropy can be reversed."},["zh"]={"熵灭也可逆转。"}},["zh"]="信念的棱镜"},["Prized Pain, Iron Ring"]={["base"]="Iron Ring",["en"]="Prized Pain",["flavour"]={["en"]={"Agony brings clarity to those of pure mind."},["zh"]={"心灵纯粹之人可从痛苦中获得明晰。"}},["zh"]="珍藏的痛苦"},["Quatl's Molt, Serpentscale Coat"]={["base"]="Serpentscale Coat",["en"]="Quatl's Molt",["flavour"]={["en"]={"As the serpent wills."},["zh"]={"腾蛇之愿必将实现。"}},["zh"]="羽蛇之带"},["Quecholli, Crumbling Maul"]={["base"]="Crumbling Maul",["en"]="Quecholli",["flavour"]={["en"]={"\"The finest prosperity grows from the direst","carnage. Such is the nature of progress.\"","- Doryani of the Vaal"},["zh"]={"“富贵总是险中求，","但财货乃身外之物，哪会问去留。”","——瓦尔族多里亚尼"}},["zh"]="重击之锤"},["Queen of the Forest, Smuggler Coat"]={["base"]="Smuggler Coat",["effectBlocks"]={{["lines"]={"Increases Movement Speed by 25%, plus 1% per # Evasion Rating, up to a maximum of 75%","Other Modifiers to Movement Speed except for Sprinting do not apply"},["order"]={1},["zh"]="提高移动速度 25%，每 # 点闪避值额外提高 1%，最高 75%\n其他除冲刺外的移动速度词缀无法生效"}},["en"]="Queen of the Forest",["flavour"]={["en"]={"Shedding away her regal past,","she forged a new destiny.","Sacrificing the ephemeral joys of man,","she embraced the eternal grasp of nature.","Seizing her one true wish,","she found peace at last."},["zh"]={"他人抚慰，仅得苦痛暂缓，","回归自然，方是永恒终站。"}},["zh"]="森林之后"},["Quill Rain, Shortbow"]={["base"]="Shortbow",["en"]="Quill Rain",["flavour"]={["en"]={"\"The rain of a thousand quills that whittle","present into past, life into death.\"","- Rigwald of the Ezomytes"},["zh"]={"“万矢齐发，战事皆往，生者皆亡。”","——艾兹麦人瑞佛"}},["zh"]="骤雨之弦"},["Radiant Grief, Lace Hood"]={["base"]="Lace Hood",["en"]="Radiant Grief",["flavour"]={["en"]={"No man burns alone."},["zh"]={"行于烈火之人并不孤独。"}},["zh"]="辉煌遗恨"},["Rampart Raptor, Tense Crossbow"]={["base"]="Tense Crossbow",["en"]="Rampart Raptor",["flavour"]={["en"]={"\"His approach to the gate was met with sounding trumpets","and an unfurling of banners. He never saw it coming.\"","- anonymous Brotherhood of Silence report"},["zh"]={"“他来到大门前，只闻嘹亮的号角","只见舒展的旌旗，令他始料不及。”","— 不知其名的寂静联盟报告"}},["zh"]="要塞的猛禽"},["Rathpith Globe, Sacred Focus"]={["base"]="Sacred Focus",["en"]="Rathpith Globe",["flavour"]={["en"]={"The Vaal emptied their slaves of beating hearts,","and left a mountain of twitching dead."},["zh"]={"瓦尔帝国建立在无数人的血汗之上，","为之付出的人们如今却已化为尘埃。"}},["zh"]="献祭之心"},["Rearguard, Blunt Quiver"]={["base"]="Blunt Quiver",["en"]="Rearguard",["flavour"]={["en"]={"\"It's a rare man that has eyes in the back of his head.\"","- Kiravi, Vaal Archer"},["zh"]={"“很少人能像背后生出双眼一般地感应空气的流动。”","——瓦尔箭术师奇拉维"}},["zh"]="寒锋之卫"},["Redblade Banner, Heraldric Tower Shield"]={["base"]="Heraldric Tower Shield",["en"]="Redblade Banner",["flavour"]={["en"]={"Blood shed is blood shared."},["zh"]={"流血等同分享血液。"}},["zh"]="红刃旗帜"},["Redemption, Trarthan Cannon"]={["base"]="Trarthan Cannon",["effectBlocks"]={{["lines"]={"Gain 1 Explosive Rhythm every # times you use a Grenade Skill","Remove all Explosive Rhythm on reaching 10 to gain Explosive Fervour for 10 Seconds"},["order"]={1},["zh"]="每使用 # 次榴弹技能，获得 1 层爆破韵律\n达到 10 层时，移除所有爆破韵律并获得持续 10 秒的爆破热忱"}},["en"]="Redemption",["flavour"]={["en"]={"\"The time has passed for diplomacy!","If they will not respect House Azadi,","then let them die gloriously... and loudly.","We are the masters of the Death Trades!\"","- Ratha Azadi"},["zh"]={"“外交的时代已经过去！","如果阿扎迪家族得不到尊重，","那就让他们光荣而响亮地赴死。","我们是亡命买卖的大师！”","— 拉莎·阿扎迪"}},["zh"]="救赎"},["Redflare Conduit, Anchorite Garb"]={["base"]="Anchorite Garb",["en"]="Redflare Conduit",["flavour"]={["en"]={"In all things, control."},["zh"]={"万事万物，皆有掌控。"}},["zh"]="赫耀导体"},["Revered Resin, Amber Amulet"]={["base"]="Amber Amulet",["en"]="Revered Resin",["flavour"]={["en"]={"The sacred sap flows slowly, but surely."},["zh"]={"纯洁的树脂缓缓流动。"}},["zh"]="神圣树脂"},["Reverie, Shaman Mantle"]={["base"]="Shaman Mantle",["effectBlocks"]={{["lines"]={"Cannot use Life Flasks","Non-Unique Life Flasks apply their Effects constantly","Recovery from Life Flasks cannot be Instant","Recovery from your Life Flasks cannot be applied to anything other than you"},["order"]={},["zh"]="无法使用生命药剂\n非传奇生命药剂的效果持续生效\n生命药剂的回复效果无法瞬间完成\n你的生命药剂回复效果仅对你自己生效"}},["en"]="Reverie",["flavour"]={["en"]={"\"Do not despair! Give yourself to the woods!","Become empty, and the Goddess will find you.","From within her roots... you shall be restored.\"","- Cirel of Caer Tarth"},["zh"]={"“不要绝望！将你自己献给森林！","变得空无，女神便会找到你。","在她的根须之中……你将被恢复。”","——赛尔塔斯的西雷尔"}},["zh"]="幻梦曲"},["Rise of the Phoenix, Omen Crest Shield"]={["base"]="Omen Crest Shield",["en"]="Rise of the Phoenix",["flavour"]={["en"]={"My bearer shall be guarded by flame,","for I am the phoenix, forever radiant in glory."},["zh"]={"持此护盾，圣火护卫，","吾乃凤凰，光灿永辉。"}},["zh"]="烈炎之翼"},["Rite of Passage, Golden Charm"]={["base"]="Golden Charm",["en"]="Rite of Passage",["flavour"]={["en"]={"To become a warrior and a hunter, each young","Azmeri must prove themselves before the Spirit."},["zh"]={"要想成为战士和猎手，每个年轻的","阿兹莫里人都必须在万灵面前证明自己。"}},["zh"]="仪式通道"},["Rondel de Ezo, Plated Buckler"]={["base"]="Plated Buckler",["en"]="Rondel de Ezo",["flavour"]={["en"]={"\"Resist for long enough, and your oppressor","will lose his will. Then, you've won.\""},["zh"]={"“只要坚持抵抗，暴君终会灰心。","那便是胜利的日子。”"}},["zh"]="艾佐的诗篇"},["Rondel of Fragility, Lunar Amulet"]={["base"]="Lunar Amulet",["en"]="Rondel of Fragility",["flavour"]={["en"]={"Fanatics are the most dangerous enemy,","for they care not for their own survival."},["zh"]={"狂热之人最为危险，","他们早已枉顾安危。"}},["zh"]="脆弱的诗文"},["Runeseeker's Call, Runic Fork"]={["base"]="Runic Fork",["en"]="Runeseeker's Call",["flavour"]={["en"]={"Smithed from ancient metal","wrought from the very stars.","It is a means to call upon them,","for one capable of wielding it."},["zh"]={"“来自星辰之体，","锻自远古金属。","这是召唤群星的秘术，","唯有能者才能使用。”"}},["zh"]="符文猎手的呼唤"},["Ryslatha's Coil, Ornate Belt"]={["base"]="Ornate Belt",["en"]="Ryslatha's Coil",["flavour"]={["en"]={"All creatures have the potential for greatness or unequivocal failure."},["zh"]={"所有生物都有干成大事或是贻笑大方的潜质。"}},["zh"]="瑞斯拉萨的线圈"},["Sacred Flame, Shrine Sceptre"]={["base"]="Shrine Sceptre",["en"]="Sacred Flame",["flavour"]={["en"]={"Fire destroys, but fire also purifies.","Life always springs anew."},["zh"]={"烈火带来破坏，火焰送来净化，","生命也将孕育一新。"}},["zh"]="神圣之火"},["Sacrosanctum, Corvus Mantle"]={["base"]="Corvus Mantle",["en"]="Sacrosanctum",["flavour"]={["en"]={"The Twilight Order rejected the gods, choosing","instead to put their faith in each other."},["zh"]={"暮光会拒绝侍奉神明，","选择将信仰赋予彼此。"}},["zh"]="奉圣庇护所"},["Sadist's Mercy, Flanged Mace"]={["base"]="Flanged Mace",["en"]="Sadist's Mercy",["flavour"]={["en"]={"\"You mortals are insidious. You repress your","evil, or deny it exists. Liars! When I open","your heads, that violence floods out.\"","- The Raven Trickster"},["zh"]={"“凡人真是阴险。","要么压抑内心的邪恶，要么否认它的存在。一群骗子！","等我打开你们的脑袋，那暴力便会奔涌而出。”","— 黑鸦欺诈者"}},["zh"]="施虐者的慈悲"},["Saffell's Frame, Emblem Crest Shield"]={["base"]="Emblem Crest Shield",["en"]="Saffell's Frame",["flavour"]={["en"]={"A swift mind solves problems before they occur."},["zh"]={"机智心灵总能预测危难。"}},["zh"]="萨费尔的智慧"},["Safrin's Resolve, Ring"]={["base"]="Ring",["en"]="Safrin's Resolve",["flavour"]={["en"]={"The Vaal protected those who integrated into their","culture. Many neighbours became one. Sekhema Safrin","vowed the Maraketh identity would remain resolute."},["zh"]={"瓦尔接纳了那些融入其文化的人。","众多邻邦与之合为一体。丝克玛·萨芙琳","誓言马拉克斯人的身份将坚如磐石。"}},["zh"]="萨芙琳的决心"},["Saitha's Spear, Barbed Spear"]={["base"]="Barbed Spear",["en"]="Saitha's Spear",["flavour"]={["en"]={"Born in a star of man's own make,","fused to her hand by her last mistake."},["zh"]={"诞生于人造的星辰，","因她最后的错误而与手相融。"}},["zh"]="赛萨之矛"},["Sands of Silk, Shrouded Vest"]={["base"]="Shrouded Vest",["en"]="Sands of Silk",["flavour"]={["en"]={"The desert is ever flowing."},["zh"]={"沙海奔流，从不停歇。"}},["zh"]="流丝之沙"},["Sandstorm Visage, Chain Tiara"]={["base"]="Chain Tiara",["en"]="Sandstorm Visage",["flavour"]={["en"]={"A fell wind brings death."},["zh"]={"陨落之风带来死亡。"}},["zh"]="禁域面容"},["Sanguine Diviner, Bone Wand"]={["base"]="Bone Wand",["en"]="Sanguine Diviner",["flavour"]={["en"]={"One way or another, it will find what it seeks."},["zh"]={"不论如何，它终会找到目标。"}},["zh"]="赤红占卜师"},["Sanguis Heroum, Staunching Charm"]={["base"]="Staunching Charm",["effectBlocks"]={{["lines"]={"You are Immune to Bleeding"},["order"]={},["zh"]="免疫流血"}},["en"]="Sanguis Heroum",["flavour"]={["en"]={"Wraeclast has known too few true heroes.","It remembers those that stood in defiance."},["zh"]={"瓦尔克拉斯从未出过如此多的英雄豪杰。","这里会铭记那些敢于奋起反抗的勇者。"}},["zh"]="英雄血液"},["Scold's Bridle, Jade Tiara"]={["base"]="Jade Tiara",["en"]="Scold's Bridle",["flavour"]={["en"]={"\"The sharper the pain, the sharper the mind.","A curious paradox.\"","- Shavronne of Umbra"},["zh"]={"“肉体的苦痛换来清晰的脑袋。","真是个有趣的悖论。”","——黑影薛朗"}},["zh"]="禁语"},["Sculpted Suffering, Warpick"]={["base"]="Warpick",["en"]="Sculpted Suffering",["flavour"]={["en"]={"The Abyssals were created, not born,","and every moment in the light was agony."},["zh"]={"深渊之物并非自然诞生，而是外力创造。","在光明之中的每一刻，都将是痛苦煎熬。"}},["zh"]="雕琢的苦难"},["Seed of Cataclysm, Lazuli Ring"]={["base"]="Lazuli Ring",["en"]="Seed of Cataclysm",["flavour"]={["en"]={"The dawn of a new era is set into motion"},["zh"]={"新时代的黎明已经降临了"}},["zh"]="灾变的种子"},["Seeing Stars, Marching Mace"]={["base"]="Marching Mace",["en"]="Seeing Stars",["flavour"]={["en"]={"Within lies a window."},["zh"]={"它的深处潜伏着暗影。"}},["zh"]="迷星之锤"},["Seeing Stars, Plated Mace"]={["base"]="Plated Mace",["en"]="Seeing Stars",["flavour"]={["en"]={"Within lies a window."},["zh"]={"它的深处潜伏着暗影。"}},["zh"]="迷星之锤"},["Serle's Grit, Kalguuran Forgehammer"]={["base"]="Kalguuran Forgehammer",["en"]="Serle's Grit",["flavour"]={["en"]={"A common soldier from a common family kept hammering into the night","after each grueling march, his eyes afire with starlight and determination.","Few suspected that he would one day become the greatest among them."},["zh"]={"一个平民出身的普通士兵，每次残酷行军后","依然在深夜苦练，双眼燃烧着星火般的决心。","没人料到他日后会成为众人之中的传奇。"}},["zh"]="瑟尔的坚毅"},["Serpent's Egg, Gold Amulet"]={["base"]="Gold Amulet",["en"]="Serpent's Egg",["flavour"]={["en"]={"When Kabala the Serpent Queen was banished from Keth,","the Sekhemas took a single hostage as punishment."},["zh"]={"毒蛇女王卡芭菈被逐出了克斯，","众丝克玛仅仅质押了一名人质。"}},["zh"]="毒蛇之卵"},["Serpent's Lesson, Tonal Focus"]={["base"]="Tonal Focus",["en"]="Serpent's Lesson",["flavour"]={["en"]={"Sinuous, entwined... inextricable."},["zh"]={"蜿蜒盘曲，百转千回……难解难分。"}},["zh"]="毒蛇的训诫"},["Shackles of the Wretched, Aged Cuffs"]={["base"]="Aged Cuffs",["en"]="Shackles of the Wretched",["flavour"]={["en"]={"Captivity breeds creativity."},["zh"]={"对自由的渴望会造就无穷的希望。"}},["zh"]="悲运之缚"},["Shankgonne, Covered Sabatons"]={["base"]="Covered Sabatons",["en"]="Shankgonne",["flavour"]={["en"]={"\"Captain Hiff Greybeard accomplished what nary a Brinerot","could: he died of old age. Almost had him a dozen times","meself, if it weren't for that damn leg of his... crafty shite...\""},["zh"]={"“希夫·灰胡子船长做到了布琳洛特人永远做不到的事：","自然老死。我差点亲自弄死他十几回，","全怪他那条该死的腿……狡猾的老东西”"}},["zh"]="藏锋"},["Shavronne's Satchel, Fine Belt"]={["base"]="Fine Belt",["en"]="Shavronne's Satchel",["flavour"]={["en"]={"Bring mystery to life. Again and again."},["zh"]={"一次又一次，令生命萌生谜团。"}},["zh"]="薛朗的背包"},["Shyaba, Temple Maul"]={["base"]="Temple Maul",["en"]="Shyaba",["flavour"]={["en"]={"Be not deceived by the treachery of men."},["zh"]={"莫被人之诡诈所欺。"}},["zh"]="席亚巴"},["Sierran Inheritance, Marabout Garb"]={["base"]="Marabout Garb",["en"]="Sierran Inheritance",["flavour"]={["en"]={"Born among the high peaks, many Mutewind","live their entire lives in snow and ice."},["zh"]={"许多哑风成员诞生于群峰之间，","终此一生都在冰天雪地中跋涉。"}},["zh"]="山岭的传承"},["Silks of Veneration, Enlightened Robe"]={["base"]="Enlightened Robe",["en"]="Silks of Veneration",["flavour"]={["en"]={"Hallowed Dordalus was cast into the pit as a heretic,","but his piety was so great, he would not burn.","He rose again, lauded, his faith forever changed...","but not the way the Templar believed."},["zh"]={"圣徒多达鲁斯被判作异端，抛入坑中，","可虔诚之心昭然，罪火无法伤其分毫。","他挺身而起，高声赞颂，信仰不曾移……","圣堂武僧却不愿相信。"}},["zh"]="敬奉之绸"},["Silverthorne, Spiked Buckler"]={["base"]="Spiked Buckler",["en"]="Silverthorne",["flavour"]={["en"]={"As a boy, in the arena, Daresso learned to","feign weakness to open up a lethal blow."},["zh"]={"青年的德瑞索踏上了竞技场，","学会了示敌以弱，扮猪吃虎。"}},["zh"]="银芒荆棘"},["Sine Aequo, Grand Manchettes"]={["base"]="Grand Manchettes",["en"]="Sine Aequo",["flavour"]={["en"]={"The greatest warrior of his era fought with honour."},["zh"]={"那时代最伟大的战士都心怀荣耀。"}},["zh"]="公理不存"},["Sire of Shards, Chiming Staff"]={["base"]="Chiming Staff",["effectBlocks"]={{["lines"]={"Spells fire # additional Projectiles","Spells fire Projectiles in a circle"},["order"]={1},["zh"]="法术发射 # 个额外投射物\n法术以环形发射投射物"}},["en"]="Sire of Shards",["flavour"]={["en"]={"That which was broken may yet break."},["zh"]={"往昔战败遭破，来日亦可破敌。"}},["zh"]="破碎传承者"},["Skin of the Loyal, Garment"]={["base"]="Garment",["en"]="Skin of the Loyal",["flavour"]={["en"]={"We happily give our limbs.","A net woven to keep safe the bones of the Lords."},["zh"]={"献上我们的身躯，","捍卫领主的遗产。"}},["zh"]="忠诚之肤"},["Skysliver, Winged Spear"]={["base"]="Winged Spear",["en"]="Skysliver",["flavour"]={["en"]={"Heads fall to the sand, just as the star fell from the sky"},["zh"]={"首级滚落杀害，星辰坠落天际。"}},["zh"]="苍穹裂片"},["Slivertongue, Zealot Bow"]={["base"]="Zealot Bow",["en"]="Slivertongue",["flavour"]={["en"]={"A hundred blind heads, each seeking the taste of prey on the air."},["zh"]={"血肉的气味弥漫于空气中。"}},["zh"]="白银之舌"},["Snakebite, Spined Bracers"]={["base"]="Spined Bracers",["en"]="Snakebite",["flavour"]={["en"]={"As the serpent shuns thought,","It shuns fear.","It strikes with the speed of wrath","And the skill of compulsion."},["zh"]={"当巨蛇不再多虑，","它变得无所畏惧。","愤恨难平，迅速杀敌！","展现气血狂怒的战技。"}},["zh"]="蝮吻"},["Snakepit, Pearl Ring"]={["base"]="Pearl Ring",["en"]="Snakepit",["flavour"]={["en"]={"They wrap around you until your blood turns as cold as theirs."},["zh"]={"用鲜血灌溉它，让它的残暴更加的嗜血。"}},["zh"]="蛇穴"},["Solus Ipse, Grand Visage"]={["base"]="Grand Visage",["en"]="Solus Ipse",["flavour"]={["en"]={"One warrior alone survived to face the Arbiter."},["zh"]={"只有一个幸存的战士与仲裁官交锋。"}},["zh"]="形单影只"},["Soul Mantle, Sacrificial Mantle"]={["base"]="Sacrificial Mantle",["en"]="Soul Mantle",["flavour"]={["en"]={"The greatest mistakes cause suffering","long after they have been made"},["zh"]={"最严重之过犯，让人吃苦受难。","即使事过境迁，依然阴魂不散。"}},["zh"]="祖灵之约"},["Soul Tether, Long Belt"]={["base"]="Long Belt",["en"]="Soul Tether",["flavour"]={["en"]={"Vaal bloodpriests were among the earliest intellectuals on record.","It was they who found that a newly freed soul would","desperately cling to any other source of life."},["zh"]={"瓦尔赤红先师是史料可考的最早的知识分子。","他们最先发现刚脱离的躯壳之灵会不顾一切地附身在其他生命形式上。"}},["zh"]="灵魂羁绊"},["Spire of Ire, Helix Spear"]={["base"]="Helix Spear",["en"]="Spire of Ire",["flavour"]={["en"]={"The spear was specially forged to assassinate Voll,","but Maligaro never got a chance to use it..."},["zh"]={"这把长矛是为了行刺福尔而专门打造的，","但马雷格罗从未有过动手的机会……"}},["zh"]="怨怒塔矛"},["Spiteful Floret, Nettle Talisman"]={["base"]="Nettle Talisman",["en"]="Spiteful Floret",["flavour"]={["en"]={"If you see the blushing tree of the northern woods,","remember: \"Blossoms of red, the tree's been fed.","Blossoms of white, prepare for a fight.\""},["zh"]={"若你见北方林间那羞红之树，","请谨记：“红花绽放，树已饱餐；","白花绽放，迎战莫缓。”"}},["zh"]="怨毒之花"},["Splinter of Lorrata, Hardwood Spear"]={["base"]="Hardwood Spear",["en"]="Splinter of Lorrata",["flavour"]={["en"]={"The Baleful Gem's corruption lingers still..."},["zh"]={"邪影宝石的腐化仍在继续……"}},["zh"]="罗瑞塔的破片"},["Splinterheart, Recurve Bow"]={["base"]="Recurve Bow",["en"]="Splinterheart",["flavour"]={["en"]={"The forests of the Vastiri held many secrets","mystical and dark. Men learned not to wander,","lest they return with a strange new purpose."},["zh"]={"瓦斯提里的森林隐藏着许多奥妙","神秘与黑暗令人们不愿踏入其中，","以免回归之时肩负起奇异的使命。"}},["zh"]="裂心之弦"},["Split Personality, Ruby"]={["base"]="Ruby",["en"]="Split Personality",["flavour"]={["en"]={"\"Try on another life. See how it fits. You'll","find that your one life is utterly inadequate.\"","- He of Many Names and Many Faces"},["zh"]={"“试试另一种人生。看看合不合身。","你会发现，你仅有一次的人生根本不够用。”","— 千面千名者"}},["zh"]="人格分裂"},["Starkonja's Head, Leatherbound Hood"]={["base"]="Leatherbound Hood",["en"]="Starkonja's Head",["flavour"]={["en"]={"There was no hero made out of Starkonja's death,","but merely a long sleep made eternal."},["zh"]={"斯塔空加死去，并未造就英雄豪杰，","只是永远长眠冥界。"}},["zh"]="斯塔空加之首"},["Stone of Lazhwar, Lapis Amulet"]={["base"]="Lapis Amulet",["en"]="Stone of Lazhwar",["flavour"]={["en"]={"You are slow, foolish and ignorant.","I am not."},["zh"]={"众人迟钝昏庸，愚昧无知。","唯我迅捷聪颖，博学睿智。"}},["zh"]="拉兹瓦的灵石"},["Strugglescream, Stellar Amulet"]={["base"]="Stellar Amulet",["en"]="Strugglescream",["flavour"]={["en"]={"There is no light at the end of this inner strife,","but the shadows eventually become home."},["zh"]={"内心的纠葛看不到尽头，","但暗影终将在此处扎根。"}},["zh"]="困苦尖啸"},["Sunsplinter, Array Buckler"]={["base"]="Array Buckler",["en"]="Sunsplinter",["flavour"]={["en"]={"\"Lundara held back the hordes, while Solerai rose to split the sky.","With a single stroke, she ended the Winter of the World.\"","- Wranga, tale-woman of the Wahida akhara"},["zh"]={"“兰拉阻挡众人之际，索瑞腾空击碎了天穹。","凭此一击，世界之冬终于走到了尽头。”","——乌兰嘉，瓦希达阿卡拉的说书人"}},["zh"]="烈阳残片"},["Surefooted Sigil, Jade Amulet"]={["base"]="Jade Amulet",["en"]="Surefooted Sigil",["flavour"]={["en"]={"Natural grace is born, not earned."},["zh"]={"自然的恩赐源于天赋，而非争取。"}},["zh"]="稳步法印"},["Surge of the Tide, Lumbering Talisman"]={["base"]="Lumbering Talisman",["effectBlocks"]={{["lines"]={"Every second Slam Skill you use while Shapeshifted is Ancestrally Boosted","Every second Strike Skill you use while Shapeshifted is Ancestrally Boosted"},["order"]={},["zh"]="变形时，你每次使用的第二个猛击技能会获得先祖加持\n变形时，你每次使用的第二个打击技能会获得先祖加持"}},["en"]="Surge of the Tide",["flavour"]={["en"]={"\"A traditional hatungo does not carry an axe,","it is true. But as Narumoa showed us, there","are many ways to crush one's enemy...\""},["zh"]={"\"传统的哈图纳格斯确实不持战斧，","但正如纳鲁摩奥所展示的——","击溃敌人的方式……从来不止一种。\""}},["zh"]="奔涌潮汐"},["Svalinn, Crucible Tower Shield"]={["base"]="Crucible Tower Shield",["en"]="Svalinn",["flavour"]={["en"]={"The priests found the Great Shield the night it fell to Middengard,","but it was the smiths who delved into the secrets it held."},["zh"]={"巨盾坠入米登加德，当夜便入先师之手，","但深究其中奥妙的却是那些匠人。"}},["zh"]="斯瓦林"},["Sylvan's Effigy, Stoic Sceptre"]={["base"]="Stoic Sceptre",["en"]="Sylvan's Effigy",["flavour"]={["en"]={"Darkness howls through ancient bones, a wistful cry","on hollow winds. The moon listens. The pack gathers."},["zh"]={"黑暗呼啸于古骸之间，是空穴之风里怅然的悲鸣。","明月倾听。狼群啸聚。"}},["zh"]="森林灵像"},["Tabula Rasa, Garment"]={["base"]="Garment",["en"]="Tabula Rasa",["zh"]="无尽之衣"},["Tangletongue, Forked Spear"]={["base"]="Forked Spear",["en"]="Tangletongue",["flavour"]={["en"]={"\"In the hands of Orbala, it made a god bleed.\"","- Wranga, tale-woman of the Wahida akhara"},["zh"]={"“在欧巴拉手中，它曾令真神流血。”","— 乌兰嘉，瓦希达阿卡拉的说书人"}},["zh"]="纠缠之舌"},["Taryn's Shiver, Gelid Staff"]={["base"]="Gelid Staff",["en"]="Taryn's Shiver",["flavour"]={["en"]={"Shed by the winged beast of night,","A scaly frost-encrusted thorn.","All who feel its wintry light","Shiver in pain at the frozen dawn."},["zh"]={"带翼野兽在夜里脱胎换骨，","蜕下寒霜覆盖的带麟犄角。","众人感受到凛冬寒光冷酷，","无不浑身颤抖，凄厉尖啸。"}},["zh"]="塔林的颤栗之语"},["Temporalis, Silk Robe"]={["base"]="Silk Robe",["en"]="Temporalis",["flavour"]={["en"]={"The final element the tale-women","mastered was Time itself."},["zh"]={"说书人最后掌握的元素","乃是时光本身。"}},["zh"]="时空之肌"},["Tetzlapokal's Desire, Votive Raiment"]={["base"]="Votive Raiment",["en"]="Tetzlapokal's Desire",["flavour"]={["en"]={"A faith born of flesh."},["zh"]={"诞生自肉体凡胎的一缕信念。"}},["zh"]="特兹拉波卡尔的欲望"},["The Adorned, Diamond"]={["base"]="Diamond",["en"]="The Adorned",["flavour"]={["en"]={"At their height, the Vaal glittered under the sun.","A decade, a century, an aeon of prosperity...","now nothing more than a passing wonder."},["zh"]={"瓦尔至盛年代，沐艳阳而烁金辉。","昌荣十年百年，绵延至千秋万代……","如今追思奇迹，都只是过眼云烟。"}},["zh"]="浮华"},["The Anvil, Bloodstone Amulet"]={["base"]="Bloodstone Amulet",["en"]="The Anvil",["flavour"]={["en"]={"Forge your Perseverance on the Anvil of Faith."},["zh"]={"让那信仰的铁砧将你无比的毅力千锤百炼。"}},["zh"]="信念之砧"},["The Auspex, Exquisite Vest"]={["base"]="Exquisite Vest",["en"]="The Auspex",["flavour"]={["en"]={"\"The boy is a bad omen,\" he cried. \"Ravens gather","before him!\" That night, a new raven appeared, and","shadowed the Auspex for the rest of his days."},["zh"]={"“这孩子是个不祥之兆，”他哭喊道，“乌鸦在他面前集结！”当晚，一只新乌鸦出现了，并在余生中一直跟随着那位占星者。"}},["zh"]="占星师"},["The Barrow Dweller, Rogue Armour"]={["base"]="Rogue Armour",["en"]="The Barrow Dweller",["flavour"]={["en"]={"In the mists they dwell,","forever hungry,","forever cold."},["zh"]={"它们深居于迷雾中，","永远饥肠辘辘，","永远阴冷相随。"}},["zh"]="荒坟寄主"},["The Black Cat, Grounding Charm"]={["base"]="Grounding Charm",["effectBlocks"]={{["lines"]={"Immune to Shock"},["order"]={},["zh"]="免疫感电"}},["en"]="The Black Cat",["flavour"]={["en"]={"The most beloved member of every Brinerot crew","is the one that refuses to do any actual work."},["zh"]={"在布琳洛特的每艘船上，","最讨人喜爱的家伙都是从不干活儿的那个。"}},["zh"]="黑猫"},["The Black Doubt, Hexer's Robe"]={["base"]="Hexer's Robe",["effectBlocks"]={{["lines"]={"Damage over Time bypasses your Energy Shield","While not on Full Life, Sacrifice #% of maximum Mana per Second to Recover that much Life"},["order"]={1},["zh"]="持续伤害穿透你的能量护盾\n非满血状态时，每秒献祭 #% 的魔力上限，以回复等量的生命"}},["en"]="The Black Doubt",["flavour"]={["en"]={"Suspicion is a sinister shadow slithering in the soul."},["zh"]={"猜忌如同邪影，深伏人之内心。"}},["zh"]="疑心暗惑"},["The Black Insignia, Corsair Cap"]={["base"]="Corsair Cap",["en"]="The Black Insignia",["flavour"]={["en"]={"Brinerot pirates live in a perpetual blaze of glory,","pushing their luck right to the end."},["zh"]={"布琳洛特的海盗永远在追逐荣耀。","并将自己的好运挥霍一空。"}},["zh"]="黑盗勋章"},["The Blood Thorn, Wrapped Quarterstaff"]={["base"]="Wrapped Quarterstaff",["en"]="The Blood Thorn",["flavour"]={["en"]={"Touch not the thorn, for only blood and pain await."},["zh"]={"手中所触荆棘之外，","满溢鲜血苦痛不断。"}},["zh"]="血棘"},["The Brass Dome, Champion Cuirass"]={["base"]="Champion Cuirass",["en"]="The Brass Dome",["flavour"]={["en"]={"The turtle's shell one day becomes its tomb."},["zh"]={"保护乌龟的龟壳同时也是它的棺材。"}},["zh"]="巨铜之顶"},["The Bringer of Rain, Decorated Helm"]={["base"]="Decorated Helm",["effectBlocks"]={{["lines"]={"Has # Augment Sockets"},["order"]={1},["zh"]="拥有 # 个增幅器插槽"}},["en"]="The Bringer of Rain",["flavour"]={["en"]={"\"What lies beneath your feet?!\"","\"Sacred ground, watered with tears of blood!\""},["zh"]={"“汝足下所踏何处？”","“此乃血泪浇灌之圣地。”"}},["zh"]="祭礼之雨"},["The Burden of Shadows, Chiming Staff"]={["base"]="Chiming Staff",["en"]="The Burden of Shadows",["flavour"]={["en"]={"Nothingness is loathe to relinquish its grip.","Every moment is a struggle to exist."},["zh"]={"虚无不肯罢休，不愿放手。","每时每刻皆为存在而抗争。"}},["zh"]="暗影的重负"},["The Burrower, Topaz Ring"]={["base"]="Topaz Ring",["en"]="The Burrower",["flavour"]={["en"]={"It coils deeper and deeper","It slithers between thoughts","It lies beneath the valley","It lies in our minds"},["zh"]={"它越钻越深，","在思绪中蠕行，","安睡在山谷中，","沉眠在心里"}},["zh"]="挖掘者"},["The Coming Calamity, Heroic Armour"]={["base"]="Heroic Armour",["en"]="The Coming Calamity",["flavour"]={["en"]={"Whiff of cold, tiny spark, faintest flicker in the dark.","Embers swirl, ice takes form, sky exposed - Death's perfect storm.","Frost and thunder, flames shine bright, ruin walks the land tonight.","By your hand they dance and bend, wield them and brook no end."},["zh"]={"寒冷气息，渺小火光，黑暗中额外明亮","余火旋转，冰霜自燃，死亡风暴转瞬就到","霜与雷，火与光，今夜将陆地燃成荒","你手中，皆臣服，征服战火愿天不亮"}},["zh"]="灵魂甲胄"},["The Covenant, Altar Robe"]={["base"]="Altar Robe",["en"]="The Covenant",["flavour"]={["en"]={"My Soul is your Strength","My Price is your Blood"},["zh"]={"我的灵魂将引导你勇闯天涯，","但是必须以鲜血做为代价。"}},["zh"]="血誓"},["The Dancing Mirage, Wayfarer Jacket"]={["base"]="Wayfarer Jacket",["en"]="The Dancing Mirage",["flavour"]={["en"]={"Be not where death falls."},["zh"]={"莫与死神同路。"}},["zh"]="跃舞蜃影"},["The Dark Defiler, Rattling Sceptre"]={["base"]="Rattling Sceptre",["en"]="The Dark Defiler",["flavour"]={["en"]={"Rare is the Necromancer who leads","his undead armies from the front."},["zh"]={"少有死灵法师立于阵前，","亲率亡者大军冲锋陷阵。"}},["zh"]="黑暗渎神"},["The Deepest Tower, Spiritbone Crown"]={["base"]="Spiritbone Crown",["en"]="The Deepest Tower",["flavour"]={["en"]={"Death crawls in darkness, closer than we think."},["zh"]={"死亡潜于黑暗，近在你我身旁。"}},["zh"]="深邃幽塔"},["The Devouring Diadem, Wicker Tiara"]={["base"]="Wicker Tiara",["en"]="The Devouring Diadem",["flavour"]={["en"]={"The spirit hungers for the flesh."},["zh"]={"灵魂渴盼重获血肉。"}},["zh"]="吞噬者王冠"},["The Empty Roar, Cultist Greathammer"]={["base"]="Cultist Greathammer",["en"]="The Empty Roar",["flavour"]={["en"]={"Secrecy and silence are powers all their own."},["zh"]={"守秘和沉默自有其力量。"}},["zh"]="空荡怒吼"},["The Eternal Spark, Crystal Focus"]={["base"]="Crystal Focus",["en"]="The Eternal Spark",["flavour"]={["en"]={"A flash of blue, a stormcloud's kiss,","her motionless dance the pulse of bliss"},["zh"]={"闪过的碧影，雷云的亲吻，","她静止的舞步中脉动着喜悦"}},["zh"]="永恒火花"},["The Everlasting Gaze, Azure Amulet"]={["base"]="Azure Amulet",["en"]="The Everlasting Gaze",["flavour"]={["en"]={"What they saw was what they believed, and","they believed Lunaris had not abandoned them."},["zh"]={"相信的一切映射在他们眼前，","他们相信月影不会抛弃他们。"}},["zh"]="永恒凝望"},["The Fall of the Axe, Silver Charm"]={["base"]="Silver Charm",["en"]="The Fall of the Axe",["flavour"]={["en"]={"\"When the headsman's blade swings,","your last moments stretch to eternity.\"","- Vorm, the Twice-Pardoned"},["zh"]={"“处刑者挥起大刀之时，","最后一刻便永远定格。”","——被特赦两次的沃尔姆"}},["zh"]="落刃时刻"},["The Fallen Formation, Lamellar Mail"]={["base"]="Lamellar Mail",["en"]="The Fallen Formation",["flavour"]={["en"]={"\"I will never forget. I will carry your memory","forward, all of you, from this ghastly Vale.\"","- Artair, last survivor of the Ogham rebellion"},["zh"]={"“我绝不会忘记。我会背负你们的回忆，","带你们每一个人，走出这该死的谷地。”","— 阿泰尔，欧甘义军的最后幸存者"}},["zh"]="溃灭之阵"},["The Flesh Poppet, Vicious Talisman"]={["base"]="Vicious Talisman",["effectBlocks"]={{["lines"]={"Copy a random Modifier from each enemy in your Presence when","you Shapeshift to an Animal form","Modifiers gained this way are lost after # seconds or when you next Shapeshift"},["order"]={1},["zh"]="当你变形成动物形态时，从在场的每名敌人处随机复制一个词缀\n该类词缀在 # 秒后或在你再次变形时消失"}},["en"]="The Flesh Poppet",["flavour"]={["en"]={"Long ago, the witches of the Azak Tribe learned","how to tap into the flow of Vivid lifeforce to","'cooperate' with their enemies... forcefully."},["zh"]={"昔日，阿扎卡部落的女巫们掌握了","驾驭鲜活命能流的方法，","以此与敌人进行“合作”——强制合作。"}},["zh"]="血肉傀儡"},["The Gnashing Sash, Wide Belt"]={["base"]="Wide Belt",["en"]="The Gnashing Sash",["flavour"]={["en"]={"\"Ghorr knows only hunger, only ravenous feasting.","It will consume all that lives, and more!\"","- Rantings of a Templar prisoner, page fourteen"},["zh"]={"“咕尔欲壑难填，一心纵情饕餮。","它将吞噬所有生灵，乃至万物！”","— 圣堂囚犯的胡言，第十四页"}},["zh"]="狂獠饰带"},["The Hammer of Faith, Giant Maul"]={["base"]="Giant Maul",["en"]="The Hammer of Faith",["flavour"]={["en"]={"The secret Order endured by publicly","praying however the Templars demanded.","One day, justice would fall upon them..."},["zh"]={"暮光会对圣堂教团逆来顺受","以公开祈祷换得了一线生机。","而总有一天，制裁必将降临。"}},["zh"]="信仰之锤"},["The Hollow Mask, Hewn Mask"]={["base"]="Hewn Mask",["en"]="The Hollow Mask",["flavour"]={["en"]={"The roots burrow deeper, unveiling the wood's bounty..."},["zh"]={"根须深扎，尽显林木之丰饶……"}},["zh"]="空洞面罩"},["The Infinite Pursuit, Bronze Greaves"]={["base"]="Bronze Greaves",["en"]="The Infinite Pursuit",["flavour"]={["en"]={"We move to be closer to her, but the distance yet grows."},["zh"]={"我们亦步亦趋，却是渐行渐远。"}},["zh"]="无尽之距"},["The Knight-errant, Mail Sabatons"]={["base"]="Mail Sabatons",["en"]="The Knight-errant",["flavour"]={["en"]={"Some search forever for their path."},["zh"]={"有些人永远在寻找自己的道路。"}},["zh"]="豪侠骑士"},["The Last Lament, Desolate Crossbow"]={["base"]="Desolate Crossbow",["en"]="The Last Lament",["flavour"]={["en"]={"\"And here we shall remain...","trapped in our symphony of eternal anguish.","Artist and Composer, their fates entwined for all of time.\"","- Adamantia Brektov, the Composer"},["zh"]={"“我们将永远在此留驻……","由永恒苦痛的交响困缚。","画师与作曲者，两者命运自此缠纠。”","— 阿达曼缇娅·布雷克托夫，作曲家"}},["zh"]="末后哀歌"},["The Lethal Draw, Sacral Quiver"]={["base"]="Sacral Quiver",["en"]="The Lethal Draw",["flavour"]={["en"]={"Life and death ooze from the same sap."},["zh"]={"生死同源，承自一脉。"}},["zh"]="攫命"},["The Mutable Star, Cleric Vestments"]={["base"]="Cleric Vestments",["en"]="The Mutable Star",["flavour"]={["en"]={"Through every great purge, and every fiery inquisition,","the Twilight Order endured in secret."},["zh"]={"熬过净化，避过审讯，","暮光会仍在悄然扩张。"}},["zh"]="易变星辰"},["The Ordained, Grand Spear"]={["base"]="Grand Spear",["en"]="The Ordained",["flavour"]={["en"]={"May the Lightless drown in the violence of His devotion."},["zh"]={"愿暗光者沉溺于祂那暴烈的虔信之中。"}},["zh"]="天选之人"},["The Pandemonius, Lapis Amulet"]={["base"]="Lapis Amulet",["en"]="The Pandemonius",["flavour"]={["en"]={"A single moment sets in motion an eternal fall,","beneath which all are buried."},["zh"]={"剎那便能造就无尽毁坏，","一切将受掩埋。"}},["zh"]="群魔殿"},["The Prisoner's Manacles, Kalguuran Cuffs"]={["base"]="Kalguuran Cuffs",["en"]="The Prisoner's Manacles",["flavour"]={["en"]={"Only once did Maligaro wonder if he'd gone too far.","His greatest success took three entire legions to capture."},["zh"]={"这是仅有的一次，连马雷格罗都怀疑自己是否太过分了。","他至高的杰作耗费了整整三个军团来追捕。"}},["zh"]="囚徒的镣铐"},["The Rat Cage, Scout's Vest"]={["base"]="Scout's Vest",["en"]="The Rat Cage",["flavour"]={["en"]={"The truth lies inside every man, if you dig around.","Many a confession was found in the bowels of Axiom."},["zh"]={"每个人的背后都藏着一份真实，","只要你挖的够深。","坦白都藏于那真实的最深处。"}},["zh"]="疫鼠囚笼"},["The Raven's Flock, Perching Staff"]={["base"]="Perching Staff",["effectBlocks"]={{["lines"]={"#% increased Spirit Reservation Efficiency"},["order"]={1},["zh"]="精魂保留效能提高 #%"}},["en"]="The Raven's Flock",["flavour"]={["en"]={"\"Where the boy went, ravens gathered,","feasting on misery. His vile influence","spread, swift as the carnage they wrought.\""},["zh"]={"“男孩所至，乌鸦云集，","以悲苦为宴。他那恶毒的侵染蔓延，","迅如彼等造就的屠戮。”"}},["zh"]="渡鸦之群"},["The Road Warrior, Raider Plate"]={["base"]="Raider Plate",["en"]="The Road Warrior",["flavour"]={["en"]={"That most legendary caravan bandit had","one rule: never let them see you flinch."},["zh"]={"传奇匪王有一条规矩：","可以胆怯，不能露怯。"}},["zh"]="征途之士"},["The Searing Touch, Pyrophyte Staff"]={["base"]="Pyrophyte Staff",["en"]="The Searing Touch",["flavour"]={["en"]={"Burn to cinders, scar and maim,","Rule a world, bathed in flame."},["zh"]={"燃为灰烬，崩裂焚解；","斯是霸权，立于火焰。"}},["zh"]="炽炎之使"},["The Sentry, Gothic Quarterstaff"]={["base"]="Gothic Quarterstaff",["en"]="The Sentry",["flavour"]={["en"]={"The night Draven attacked,","Erian was asleep at his post."},["zh"]={"阿里安放哨偷懒的那一晚，","正是德莱文来袭的那一夜。"}},["zh"]="哨望"},["The Smiling Knight, Cowled Helm"]={["base"]="Cowled Helm",["en"]="The Smiling Knight",["flavour"]={["en"]={"He never spoke a word. His opponents imagined","their own personal mockeries, most cruel."},["zh"]={"他从不言语，对手却想象到，","那是最残酷、最刻薄的嘲弄。"}},["zh"]="笑面骑士"},["The Sunken Vessel, Knight Armour"]={["base"]="Knight Armour",["en"]="The Sunken Vessel",["flavour"]={["en"]={"\"What are you lot looking at? We're","under fire! Get to your stations!\"","- Captain Sventura, the Unlucky"},["zh"]={"“你们这帮家伙在看什么？我们正在被炮击！各就各位！”","— 斯文图拉，倒霉的船长"}},["zh"]="沉没之舟"},["The Surrender, Stone Tower Shield"]={["base"]="Stone Tower Shield",["en"]="The Surrender",["flavour"]={["en"]={"Our hearts cry out","but are silenced by our flesh","and so we give up our flesh."},["zh"]={"身体沉默了内心，","因此我们舍去肉体。"}},["zh"]="降伏"},["The Surrender, Vaal Tower Shield"]={["base"]="Vaal Tower Shield",["en"]="The Surrender",["flavour"]={["en"]={"Our hearts cry out","but are silenced by our flesh","and so we give up our flesh."},["zh"]={"身体沉默了内心，","因此我们舍去肉体。"}},["zh"]="降伏"},["The Taming, Prismatic Ring"]={["base"]="Prismatic Ring",["effectBlocks"]={{["lines"]={"Wind Skills which can be boosted by Elemental Ground Surfaces can be boosted by multiple Elemental Ground Surfaces","Wind Skills which can be boosted by Elemental Ground Surfaces count","as being boosted by Ignited, Shocked, and Chilled Ground"},["order"]={},["zh"]="可被元素地面效果加持的风系技能可被多种元素地面效果加持 可被元素地面效果加持的风系技能视作 被点燃地面，感电地面和冰缓地面加持"}},["en"]="The Taming",["flavour"]={["en"]={"\"Moon after moon did Berek make fools","Of the great and Untamed Three","Until malice for a Brother","Slew the hatred of the Other","And Berek did hunt","Alone and free.\"","- Berek and the Untamed"},["zh"]={"“贝雷克拥有无比机智，","从他和抗驯者之间的缠斗便可得知。","他让那三种元素互相角力，","直到它们露出败迹，","接着一鼓作气","让自己和恶梦远离。”","——贝雷克及抗驯者"}},["zh"]="元素之章"},["The Three Dragons, Solid Mask"]={["base"]="Solid Mask",["en"]="The Three Dragons",["flavour"]={["en"]={"\"The ice seared his naked feet","As the lightning stilled his heart,","But it was the flames upon his lover's face","That roused him to vengeance.\"","- From 'The Three Dragons' by Victario of Sarn"},["zh"]={"冰霜严寒，他的赤足伤痕布满，","雷霆万钧，他的心念无法动弹，","恶火猛烈，情人容颜化为飞灰，","此时他才终于奋起复仇，猛攻不退。","——萨恩的维多里奥著作\"猎龙记\""}},["zh"]="三龙战纪"},["The Unborn Lich, Ravenous Staff"]={["base"]="Ravenous Staff",["effectBlocks"]={{["lines"]={"#% increased Spirit Reservation Efficiency"},["order"]={1},["zh"]="精魂保留效能提高 #%"}},["en"]="The Unborn Lich",["flavour"]={["en"]={"In ghastly pits beneath the world,","Kulemak grows countless new bodies,","each more powerful than the last.","Not all of his abominations survive."},["zh"]={"在世界深处那些可怖的深坑中，","库勒马克孕育着数不清的新躯体，","一具比一具强悍。","他造出的怪物并不都能活下来。"}},["zh"]="未生巫妖"},["The Unleashed, Revered Vestments"]={["base"]="Revered Vestments",["effectBlocks"]={{["lines"]={"Gain 1 Runic Binding on Hit with Spells, no more than once every 0.5 seconds","Lose all Runic Bindings when you Shapeshift to gain that much Unbound Potential"},["order"]={},["zh"]="使用法术击中时获得 1 点符文咒缚，每 0.5 秒只能获得一次\n变形时，损失所有符文咒缚以获得等量的潜能释放"}},["en"]="The Unleashed",["flavour"]={["en"]={"His latent potential unleashed itself, a beast","bursting from its shackles. Each strike of Farrow's","hammer rang out a song for the First Ones."},["zh"]={"他的潜能骤然释放，仿若挣脱枷锁的野兽。法罗的每一记锤击，都为初生之子奏响战歌。"}},["zh"]="破禁者"},["The Vertex, Tribal Mask"]={["base"]="Tribal Mask",["en"]="The Vertex",["flavour"]={["en"]={"\"A queen should be seen, admired, but never touched.\"","- Atziri, Queen of the Vaal"},["zh"]={"“女王者，可敬观崇拜而不可亵玩焉。”","——瓦尔女王阿兹里"}},["zh"]="谜容"},["The Vile Knight, Shielded Helm"]={["base"]="Shielded Helm",["en"]="The Vile Knight",["flavour"]={["en"]={"Familiarity breeds contempt."},["zh"]={"熟门熟路会令你疏忽大意。"}},["zh"]="厄难骑士"},["The Wailing Wall, Effigial Tower Shield"]={["base"]="Effigial Tower Shield",["en"]="The Wailing Wall",["flavour"]={["en"]={"Some stories are never told."},["zh"]={"总有一些未曾言说的故事。"}},["zh"]="悲泣之壁"},["The Whispering Ice, Permafrost Staff"]={["base"]="Permafrost Staff",["en"]="The Whispering Ice",["flavour"]={["en"]={"\"From what beast you derived, we can only fathom.","Aye, you of living ice, rotting gill, and untold nightmare!","We Brinerot return ye to the sea.\"","- Weylam Roth"},["zh"]={"“你的亲族是何等兽物？我们猜测不得。","诚然，你有冰霜之躯、腐烂之鳃与未名梦魇！","布琳洛特将你送回深海。”","— 威勒姆·罗斯"}},["zh"]="冰点低语"},["The Wicked Quill, Withered Wand"]={["base"]="Withered Wand",["en"]="The Wicked Quill",["flavour"]={["en"]={"With a flick of the finger, their fates are written,","the pages torn to a million pieces."},["zh"]={"弹指一挥间，命运已书写，篇幅皆四散。"}},["zh"]="邪恶之翎"},["Thief's Torment, Emerald Ring"]={["base"]="Emerald Ring",["en"]="Thief's Torment",["flavour"]={["en"]={"The ring I stole,","My finger they took,","A shrouded mind,","Cut their curses short,","As I drained their spirit","And stole their soul.","A blessing is often a curse."},["zh"]={"我偷了枚戒指，","被人家砍下一手指，","我心已受蒙蔽，","对其诅咒漫不在意，","我吸尽他们心神，","窃取他们灵魂。","祝福往往招致咒诅。"}},["zh"]="窃罪"},["Threaded Light, Woven Focus"]={["base"]="Woven Focus",["en"]="Threaded Light",["flavour"]={["en"]={"A gift, a braid, of golden hair.","The war, forgotten.","The reason, remembered."},["zh"]={"一份礼物，一缕金色的发辫。","战争，早已被遗忘。","理由，却铭记在心。"}},["zh"]="明光丝缕"},["Thrillsteel, Spired Greathelm"]={["base"]="Spired Greathelm",["en"]="Thrillsteel",["flavour"]={["en"]={"We may fight, and we may die, but in these","moments of blood and battle, we truly live."},["zh"]={"我们可能会战斗，我们可能会战死，","但在流血和战斗的时刻，我们真正地活着。"}},["zh"]="惊险刺激"},["Thunderfist, Utility Wraps"]={["base"]="Utility Wraps",["en"]="Thunderfist",["flavour"]={["en"]={"The roar of the heavens","Strikes more than fear","Into the hearts of Man"},["zh"]={"天庭狂嚎震怒","神罚永不饶恕","人心恐惧无助"}},["zh"]="雷拳"},["Thunderstep, Steeltoe Boots"]={["base"]="Steeltoe Boots",["en"]="Thunderstep",["flavour"]={["en"]={"Where legends tread,","the world hearkens."},["zh"]={"传奇所到之处，","天地为之撼动。"}},["zh"]="雷鸣步伐"},["Tidebreaker, Pointed Maul"]={["base"]="Pointed Maul",["en"]="Tidebreaker",["flavour"]={["en"]={"The sea strikes the rock relentlessly.","Whether in one day or in ten thousand years,","eventually the rock will crumble,","and the Brine King's domain will grow."},["zh"]={"海水击岩石，","一日复一日，","待到洞穿时，","惊海之王兴。"}},["zh"]="局势逆转者"},["Titanrot Cataphract, Maraketh Cuirass"]={["base"]="Maraketh Cuirass",["en"]="Titanrot Cataphract",["flavour"]={["en"]={"Not the sound of thunder on the wind, but the","rhoaback riders—death charging from the sands."},["zh"]={"风中回荡呼啸并非雷鸣之声，","那是恐喙鸟骑士的搏命冲锋。"}},["zh"]="巨人灾星甲胄"},["Trampletoe, Trimmed Greaves"]={["base"]="Trimmed Greaves",["en"]="Trampletoe",["flavour"]={["en"]={"The truly mighty are never outnumbered."},["zh"]={"真正的力量不会屈服于数量。"}},["zh"]="踏趾靴"},["Treefingers, Riveted Mitts"]={["base"]="Riveted Mitts",["en"]="Treefingers",["flavour"]={["en"]={"The largest beings on Wraeclast","are not flesh and blood."},["zh"]={"瓦尔克拉斯最庞大的生灵","并不是血肉之躯。"}},["zh"]="树之指"},["Trenchtimbre, Spiked Club"]={["base"]="Spiked Club",["en"]="Trenchtimbre",["flavour"]={["en"]={"Ezomyte loyalty was not given to distant leaders.","It was earned by comrades in arms."},["zh"]={"艾兹麦人不会向高高在上的领袖效忠，","只有同胞战友才能赢得忠心。"}},["zh"]="战壕砥柱"},["Trephina, Forge Maul"]={["base"]="Forge Maul",["en"]="Trephina",["flavour"]={["en"]={"The art of surgery advances one mistake at a time."},["zh"]={"手术之道的进步，源于一个个错误。"}},["zh"]="穿洞奇械"},["Twisted Empyrean, Aberrant Sledge"]={["base"]="Aberrant Sledge",["en"]="Twisted Empyrean",["flavour"]={["en"]={"Infinite mutations over endless eons borne upon it in a singular moment."},["zh"]={"无尽岁月中的无数突变，于刹那之间尽数加诸其身。"}},["zh"]="扭曲天穹"},["Tyranny's Grip, Ironhead Spear"]={["base"]="Ironhead Spear",["en"]="Tyranny's Grip",["flavour"]={["en"]={"The might of the Eternal Empire was formidable,","but rebels of every culture stood together as one."},["zh"]={"永恒帝国威势滔天，","然各路仁人义士众志成城。"}},["zh"]="暴政之握"},["Uhtred's Chalice, Transcendent Mana Flask"]={["base"]="Transcendent Mana Flask",["en"]="Uhtred's Chalice",["flavour"]={["en"]={"Uhtred drank. Verisium burned through his veins.","He gazed at death's face. With all his strength,","he turned instead to the stars, and witnessed Truth."},["zh"]={"乌崔德饮下了维金。","维金在血脉中灼烧。他凝视着死亡的面庞。","他用尽全力，转而望向星辰，从而见证了真理。"}},["zh"]="乌崔德圣杯"},["Umbilicus Immortalis, Linen Belt"]={["base"]="Linen Belt",["en"]="Umbilicus Immortalis",["flavour"]={["en"]={"\"The power of rebirth rivals that of immortality.\"","- Icius Perandus, Antiquities Collection, Item 3"},["zh"]={"“不曾锈蚀绝不代表纯净。”","——伊席厄斯·普兰德斯，《珍奇古玩大典》，第3号物品"}},["zh"]="不朽系命"},["Undying Hate, Timeless Jewel"]={["base"]="Timeless Jewel",["effectBlocks"]={{["lines"]={"Glorifying the defilement of # souls in tribute to Amanamu","Passives in radius are Conquered by the Abyssals"},["order"]={1},["zh"]="赞颂以阿曼娜姆之名亵渎的 # 个灵魂\n范围内的天赋被深渊抑制"},{["lines"]={"Glorifying the defilement of # souls in tribute to Kulemak","Passives in radius are Conquered by the Abyssals"},["order"]={1},["zh"]="赞颂以库勒马克之名亵渎的 # 个灵魂\n范围内的天赋被深渊抑制"},{["lines"]={"Glorifying the defilement of # souls in tribute to Kurgal","Passives in radius are Conquered by the Abyssals"},["order"]={1},["zh"]="赞颂以古加尔之名亵渎的 # 个灵魂\n范围内的天赋被深渊抑制"},{["lines"]={"Glorifying the defilement of # souls in tribute to Tecrod","Passives in radius are Conquered by the Abyssals"},["order"]={1},["zh"]="赞颂以特克罗之名亵渎的 # 个灵魂\n范围内的天赋被深渊抑制"},{["lines"]={"Glorifying the defilement of # souls in tribute to Ulaman","Passives in radius are Conquered by the Abyssals"},["order"]={1},["zh"]="赞颂以乌拉曼之名亵渎的 # 个灵魂\n范围内的天赋被深渊抑制"}},["en"]="Undying Hate",["flavour"]={["en"]={"They believed themselves driven by necessity,","but that desperation made them monstrous."},["zh"]={"他们自认为是被逼无奈，","但正是这种绝望把他们变成了恶魔。"}},["zh"]="不朽之恨"},["Ungil's Harmony, Azure Amulet"]={["base"]="Azure Amulet",["en"]="Ungil's Harmony",["flavour"]={["en"]={"Gentle anger, raging calm."},["zh"]={"平静与愤怒有时是一体两面。"}},["zh"]="恩吉尔的和谐"},["Valako's Roar, Topaz Charm"]={["base"]="Topaz Charm",["en"]="Valako's Roar",["flavour"]={["en"]={"The sea swells, the sky thunders; two ships tilt at odds.","Flashes of light show only swinging axes... and a grin."},["zh"]={"海涛汹汹，天雷滚滚，双舸竞斗冲。","电闪破黑云，刀光映斧影，唯见寒笑森森。"}},["zh"]="瓦拉克怒吼"},["Valako's Vice, Plate Gauntlets"]={["base"]="Plate Gauntlets",["en"]="Valako's Vice",["flavour"]={["en"]={"Unlike the other gods, when he was born from the volcano,","Valako rode the clouds of ash into the thundering sky."},["zh"]={"瓦拉克自火山诞生，不同于其他神明。","他乘着灰烬之云，腾飞到雷鸣的高空。"}},["zh"]="瓦拉库的离奇"},["Veil of the Night, Martyr Crown"]={["base"]="Martyr Crown",["en"]="Veil of the Night",["flavour"]={["en"]={"The seeds of greatness are planted in darkness,","Watered by suffering,","Tended by desperation,","And bloom steel flowers of victory."},["zh"]={"伟业种籽，栽于黑暗，","蒙受苦难浇灌，","遭到绝望照管，","方能绽放胜利的铁花瓣。"}},["zh"]="夜幕"},["Veilpiercer, Amethyst Ring"]={["base"]="Amethyst Ring",["en"]="Veilpiercer",["flavour"]={["en"]={"The tribe revelled wildly, unaware that each fruit","they ate further bound their continuity to the fog's.","In time, the merest touch could break their reality."},["zh"]={"部族纵情狂欢，未觉所食的每一颗果实，","都令他们的存续与迷雾的存续愈发紧密地绑定。","日久，最轻微的触碰，也足以令他们的现实崩碎。"}},["zh"]="破幕者"},["Venopuncture, Iron Ring"]={["base"]="Iron Ring",["en"]="Venopuncture",["flavour"]={["en"]={"There is a way to survive the bite of an ice snake,","but few have the resolve to attempt it."},["zh"]={"只有一种方式能逃过冰蛇的毒牙，","但甚少有人敢下决心。"}},["zh"]="静脉穿刺"},["Ventor's Gamble, Gold Ring"]={["base"]="Gold Ring",["en"]="Ventor's Gamble",["flavour"]={["en"]={"In a blaze of glory,","An anomaly defying all odds","The \"unkillable\" beast met the divine","And Ventor met his latest trophy."},["zh"]={"至辉荣耀，劣境克敌","“不败”怪物终遭天谴","芬多取得毕生最后胜绩。"}},["zh"]="赌神芬多"},["Vestige of Darkness, Tenebrous Crown"]={["base"]="Tenebrous Crown",["en"]="Vestige of Darkness",["flavour"]={["en"]={"\"Your covetous hands bring the Unlight","ever closer to consuming your realm.\""},["zh"]={"“你贪婪的双手将暗光之域日益拉近，","直至吞噬你的国度。”"}},["zh"]="黑暗残迹"},["Vigilant View, Emerald Ring"]={["base"]="Emerald Ring",["en"]="Vigilant View",["flavour"]={["en"]={"The warriors of the Unblinking Eye moved","together as one, shoulder to shoulder."},["zh"]={"凝望之眼的战士们，","并肩同行，进退如一。"}},["zh"]="警戒凝视"},["Vis Mortis, Plated Raiment"]={["base"]="Plated Raiment",["en"]="Vis Mortis",["flavour"]={["en"]={"Reap what others have sown","Muster them from their graves","Parade them for your pleasure","Zealots in mortis enslaved"},["zh"]={"莫让前人耕耘回归尘土","休使学问埋入坟墓","呼唤前人出坟阔步，","奴役亡躯，踏上征途。"}},["zh"]="兀鸣"},["Visage of Ayah, Beaded Circlet"]={["base"]="Beaded Circlet",["en"]="Visage of Ayah",["flavour"]={["en"]={"Tale-women do not fight as dekharas.","They command a power all their own."},["zh"]={"说书人虽不像德卡拉一样征战，","却也掌控着只属于自己的力量。"}},["zh"]="阿雅的面目"},["Voices, Sapphire"]={["base"]="Sapphire",["en"]="Voices",["flavour"]={["en"]={"Only a madman would ignore a god's instructions."},["zh"]={"只有疯子才无视天神的指引。"}},["zh"]="天神之音"},["Voll's Protector, Ironclad Vestments"]={["base"]="Ironclad Vestments",["en"]="Voll's Protector",["flavour"]={["en"]={"Although a great leader during the war,","Voll proved disastrous in times of peace."},["zh"]={"福尔骁勇善战，登基称王","奈何治国无方，终至灭亡"}},["zh"]="福尔的战铠"},["Voll's Protector, Plated Vestments"]={["base"]="Plated Vestments",["en"]="Voll's Protector",["flavour"]={["en"]={"Although a great leader during the war,","Voll proved disastrous in times of peace."},["zh"]={"福尔骁勇善战，登基称王","奈何治国无方，终至灭亡"}},["zh"]="福尔的战铠"},["Voltaxic Rift, Fanatic Bow"]={["base"]="Fanatic Bow",["en"]="Voltaxic Rift",["flavour"]={["en"]={"The eldritch storm descended upon us, and bruised lightning","rained down. Metal withered and flesh melted before its","arcane power. There was no escape, no shelter. Only despair."},["zh"]={"奇异风暴在我头顶笼罩，","雷霆风暴在我眼前宣泄","秘术让手上的金属熔解，生命零凋，","奔逃无路，求助无门！绝望永不止歇……"}},["zh"]="魔暴之痕"},["Waistgate, Heavy Belt"]={["base"]="Heavy Belt",["en"]="Waistgate",["flavour"]={["en"]={"Clever artifice is not always complex."},["zh"]={"奇谋妙计不应该费尽心机。"}},["zh"]="腰际之门"},["Wake of Destruction, Secured Leggings"]={["base"]="Secured Leggings",["en"]="Wake of Destruction",["flavour"]={["en"]={"Tempest's power given form,","Flee before the walking storm."},["zh"]={"风暴成形，初生乍现，","伺机而动，逃出生天。"}},["zh"]="覆灭之兆"},["Wandering Reliquary, Steel Plate"]={["base"]="Steel Plate",["en"]="Wandering Reliquary",["flavour"]={["en"]={"Knowing she could outlast any opponent,","Wrashmin fought not to win, but to delay."},["zh"]={"华士敏深知自己能拖垮对手，","战斗时不求速胜，但求持久。"}},["zh"]="流浪圣柜"},["Wanderlust, Wrapped Sandals"]={["base"]="Wrapped Sandals",["en"]="Wanderlust",["flavour"]={["en"]={"All the world is my home."},["zh"]={"敝人以天地为家。"}},["zh"]="苦行之履"},["Waveshaper, Tideseer Mantle"]={["base"]="Tideseer Mantle",["en"]="Waveshaper",["flavour"]={["en"]={"\"Move in ways your enemy does not expect.","Confuse them with elegance and grace.","They'll never see the axe coming.\"","- Rakiata, Chieftain of the Tasalio Tribe"},["zh"]={"“行动当出其不意","以优雅身姿欺敌，","斧刃便所向无敌。”","——拉其塔，塔萨里奥部落的酋长"}},["zh"]="塑成惊涛"},["Whisper of the Brotherhood, Sapphire Ring"]={["base"]="Sapphire Ring",["en"]="Whisper of the Brotherhood",["flavour"]={["en"]={"Forged by the last remaining brother","to return all that was once given."},["zh"]={"仅存的兄弟锻造出了它，","将获赠的一切物归原主。"}},["zh"]="兄弟会的耳语"},["Widow's Reign, Knight Armour"]={["base"]="Knight Armour",["effectBlocks"]={{["lines"]={"Life that would be lost by taking Damage is instead Reserved","until you take no Damage to Life for # seconds"},["order"]={1},["zh"]="失去的生命被保留起来， 直到你的生命在 # 秒内没有再受到伤害"}},["en"]="Widow's Reign",["flavour"]={["en"]={"That day, both the Unblinking Eye and","their enemies stood in silence. That day,","the sky was clear, but it was raining."},["zh"]={"那一日，凝望之眼与宿敌","相逢却沉默无言。那一日，","晴空万里，雨却打湿了脸。"}},["zh"]="寡妇的统治"},["Widowhail, Crude Bow"]={["base"]="Crude Bow",["en"]="Widowhail",["flavour"]={["en"]={"\"I loosed a volley of arrows into the heart of the man","who slew my beloved. There was no satisfaction, no","healing, no revenge. There was only... emptiness.\""},["zh"]={"“我射出连珠箭矢飞入害我爱人的凶手的心脏。","但这并没有给我带来满足，","没有治愈，没有复仇。只留下一片……空虚。”"}},["zh"]="遗孀之雹"},["Window to Paradise, Barricade Tower Shield"]={["base"]="Barricade Tower Shield",["effectBlocks"]={{["lines"]={"Inflict Elemental Exposure to Enemies 3 metres in front of you","for 4 seconds, every 0.25 seconds while raised"},["order"]={},["zh"]="举起时，每 0.25 秒对你前方 3 米内的敌人施加\n元素曝露，持续 4 秒"}},["en"]="Window to Paradise",["flavour"]={["en"]={"\"Beyond fire, blood, and nightmare,","the Saviour will build Utopia.\""},["zh"]={"“跨越火焰、鲜血与梦魇，","救赎者必将筑起乌托邦。”"}},["zh"]="乐土之窗"},["Windscream, Feathered Sandals"]={["base"]="Feathered Sandals",["en"]="Windscream",["flavour"]={["en"]={"The mocking wind, a shielding spell,","The haunting screams, a maddening hell"},["zh"]={"恶风袭击，召出护身宝具，","尖啸不息，目睹烈刑恶狱"}},["zh"]="恶风足迹"},["Wings of Caelyn, Rusted Greathelm"]={["base"]="Rusted Greathelm",["en"]="Wings of Caelyn",["flavour"]={["en"]={"The older brother retained calm in the midst of fury."},["zh"]={"在狂怒与喧嚣之中，哥哥依然保持着冷静。"}},["zh"]="凯琳飞翼"},["Wondertrap, Silk Slippers"]={["base"]="Silk Slippers",["en"]="Wondertrap",["flavour"]={["en"]={"Wonders abound at death's door."},["zh"]={"濒临死亡之际，人总能创造奇迹。"}},["zh"]="回光之迹"},["Wulfsbane, Painted Tower Shield"]={["base"]="Painted Tower Shield",["effectBlocks"]={{["lines"]={"Permanently Intimidate enemies on Block"},["order"]={},["zh"]="格挡时永久威吓敌人"}},["en"]="Wulfsbane",["flavour"]={["en"]={"The Counts of Ogham share a","legacy of cunning and power."},["zh"]={"欧甘伯爵世袭血脉，","传承着狡黠与力量。"}},["zh"]="伍夫之难"},["Wylund's Stake, Smithing Hammer"]={["base"]="Smithing Hammer",["en"]="Wylund's Stake",["flavour"]={["en"]={"Shaped metal never forgets the forge."},["zh"]={"塑成的金属永远铭记着锻炉的锤炼。"}},["zh"]="怀伦德之桩"},["Xoph's Blood, Amber Amulet"]={["base"]="Amber Amulet",["en"]="Xoph's Blood",["flavour"]={["en"]={"We are his blood.","Through us he carries his burning message."},["zh"]={"我们是他的血肉。","透过我们，他散播炙热的启示。"}},["zh"]="索伏之血"},["Yoke of Suffering, Bloodstone Amulet"]={["base"]="Bloodstone Amulet",["en"]="Yoke of Suffering",["flavour"]={["en"]={"Let the unrepentant be dragged ever downwards by the weight of their sins."},["zh"]={"让冥顽不灵者深陷罪恶的泥沼吧。"}},["zh"]="苦难羁绊"},["Yriel's Fostering, Strider Vest"]={["base"]="Strider Vest",["en"]="Yriel's Fostering",["flavour"]={["en"]={"Feed a beast and it will not hunt.","Protect it and it will not fight.","Ferocity must be learned, not taught.","It is suffering that forges the greatest warriors."},["zh"]={"喂食野兽，它就不会伤害你·","保护它野兽 它就不会与你为敌·","暴行最易被模仿却无法被教授·","只有疼痛能够打造最强的战士·"}},["zh"]="伊瑞的精通"},["Zaida's Longevity, Ring"]={["base"]="Ring",["en"]="Zaida's Longevity",["flavour"]={["en"]={"The relative peace under the fledgling Empire saw","the first Sekhema to choose, in her resplendent age and","wisdom, to step down. The role of Zaitema was born."},["zh"]={"羽翼未丰的帝国治下相对的和平时期，","见证了首位丝克玛在其光辉岁月与智慧之年选择退位。","扎特玛这一角色由此诞生。"}},["zh"]="寨达的长寿"},["Zerphi's Genesis, Heavy Belt"]={["base"]="Heavy Belt",["en"]="Zerphi's Genesis",["flavour"]={["en"]={"The most horrifying ideas often begin with a simple innovation."},["zh"]={"最恐怖的创意，往往诞生于一个简单的创新。"}},["zh"]="泽佛伊的本源"},["Zerphi's Serape, Scalper's Jacket"]={["base"]="Scalper's Jacket",["en"]="Zerphi's Serape",["flavour"]={["en"]={"Mortality is a curse.","The cure is simple."},["zh"]={"终末乃是诅咒。","解咒轻而易举。"}},["zh"]="泽佛伊的毛披肩"}},
